INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:thailand-bangkok-grand-palace-bangkok', 'Grand Palace Bangkok', 'palace', 13.750000, 100.491300, 'Bangkok', 'Thailand', 'A vast complex of ornate royal buildings, throne halls, and pavilions built in 1782 as the official residence of the Kings of Siam. It remains used for official ceremonies and houses Wat Phra Kaew within its walls.', 'It is the single most important historical and cultural landmark in Thailand, showcasing the pinnacle of Thai royal architecture.', 180, NULL, 1, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:thailand-bangkok-wat-phra-kaew', 'Wat Phra Kaew', 'temple', 13.751500, 100.492700, 'Bangkok', 'Thailand', 'Officially the Temple of the Emerald Buddha, located on the grounds of the Grand Palace. It enshrines the Phra Kaew Morakot, a highly revered jade statue of a meditating Buddha.', 'It is the most sacred Buddhist temple in Thailand and a masterpiece of glittering mosaic and gold architecture.', 90, NULL, 1, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:thailand-bangkok-wat-arun', 'Wat Arun', 'temple', 13.743700, 100.488900, 'Bangkok', 'Thailand', 'The Temple of Dawn, a Buddhist temple on the Thonburi west bank of the Chao Phraya River, distinguished by its towering 70-meter central prang decorated with colorful porcelain. The temple dates to the Ayutthaya era.', 'Its riverside spire is the most photographed silhouette in Bangkok, especially at sunset.', 75, NULL, 1, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:thailand-bangkok-wat-pho', 'Wat Pho', 'temple', 13.746500, 100.492700, 'Bangkok', 'Thailand', 'A 16th-century Buddhist temple complex famous for housing a 46-meter-long gilded Reclining Buddha. It is also considered the birthplace of traditional Thai massage.', 'The enormous Reclining Buddha is one of Bangkok''s most awe-inspiring sights and the temple is walking distance from the Grand Palace.', 90, NULL, 1, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:thailand-bangkok-chatuchak-weekend-market', 'Chatuchak Weekend Market', 'market', 13.799900, 100.550000, 'Bangkok', 'Thailand', 'One of the world''s largest weekend markets, covering 35 acres with more than 15,000 stalls selling clothing, antiques, plants, food, and crafts. It operates primarily on Saturdays and Sundays.', 'It is a chaotic, sprawling shopping experience unlike anything else in Southeast Asia.', 180, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:thailand-bangkok-khao-san-road', 'Khao San Road', 'district', 13.759000, 100.497700, 'Bangkok', 'Thailand', 'A short street in the Banglamphu district known globally as a backpacker hub since the 1980s, lined with cheap guesthouses, street food carts, bars, and souvenir stalls. It transforms into a buzzing pedestrian party zone at night.', 'It is the most famous backpacker street in the world and a rite-of-passage Bangkok street-food experience.', 90, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:thailand-bangkok-chao-phraya-river', 'Chao Phraya River', 'river', 13.728600, 100.512600, 'Bangkok', 'Thailand', 'The major river flowing through Bangkok, historically the lifeline of the city with riverside temples, palaces, and floating commerce. Public express boats and longtail tours navigate its waters daily.', 'A ride on its public ferries is the cheapest, most scenic way to see Bangkok''s riverside landmarks.', 60, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:thailand-bangkok-jim-thompson-house', 'Jim Thompson House', 'museum', 13.749100, 100.528600, 'Bangkok', 'Thailand', 'The former home of American silk entrepreneur Jim Thompson, who mysteriously disappeared in 1967. The compound assembles six traditional Thai teakwood houses and showcases his collection of Asian art and antiques.', 'It offers a beautifully preserved glimpse of traditional Thai architecture in the middle of the modern city.', 75, NULL, 0, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:thailand-bangkok-lumphini-park', 'Lumphini Park', 'park', 13.730500, 100.541800, 'Bangkok', 'Thailand', 'Bangkok''s first and most famous public park, opened in the 1920s, covering 142 acres of green space with lakes, paddle boats, and pavilions. It is a popular spot for jogging, tai chi, and morning aerobics.', 'It is the city''s central green lung and a great place to see locals exercising at dawn alongside monitor lizards.', 60, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:thailand-bangkok-wat-saket-the-golden-mount', 'Wat Saket (The Golden Mount)', 'temple', 13.753600, 100.506700, 'Bangkok', 'Thailand', 'A historic Ayutthaya-era temple topped by an artificial hill crowned with a golden chedi enshrining Buddha relics. A spiral staircase of 344 steps leads to a panoramic terrace.', 'It offers one of the best 360-degree views of old Bangkok from the top of its iconic golden chedi.', 60, NULL, 0, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:thailand-bangkok-king-power-mahanakhon-skywalk', 'King Power Mahanakhon SkyWalk', 'observation_deck', 13.723400, 100.528500, 'Bangkok', 'Thailand', 'An observation deck atop the 314-meter Mahanakhon skyscraper, the tallest building in Bangkok for years. It features a glass tray (skywalk) extending over the edge of the rooftop.', 'It delivers the most thrilling panoramic view of the Bangkok skyline, day or night.', 75, NULL, 0, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:thailand-bangkok-asiatique-the-riverfront', 'Asiatique The Riverfront', 'market', 13.704500, 100.502400, 'Bangkok', 'Thailand', 'A large open-air night market and mall on the Chao Phraya riverfront, built on the site of a former teak trading port. It combines 1,500 boutiques, restaurants, a Ferris wheel, and ladyboy cabaret shows.', 'It is the most polished and accessible night market in Bangkok, with a scenic riverside setting.', 120, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:turkey-istanbul-hagia-sophia', 'Hagia Sophia', 'mosque', 41.008600, 28.980200, 'Istanbul', 'Turkey', 'A monumental 6th-century Byzantine basilica that later served as an Ottoman imperial mosque and a museum, now functioning again as a working mosque. Its massive dome and gold mosaics make it one of the most significant buildings in architectural history.', 'It is the single most iconic monument in Istanbul, bridging the Byzantine and Ottoman worlds in one breathtaking interior.', 90, NULL, 1, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:turkey-istanbul-blue-mosque', 'Blue Mosque', 'mosque', 41.005400, 28.976800, 'Istanbul', 'Turkey', 'The early 17th-century Sultan Ahmed Mosque, famous for its cascading domes, six minarets, and the more than 20,000 hand-painted blue Iznik tiles that line its interior. It remains an active mosque facing Hagia Sophia across Sultanahmet Square.', 'Its serene blue-tiled interior and six minarets define the Istanbul skyline alongside Hagia Sophia.', 60, NULL, 1, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:turkey-istanbul-topkapi-palace', 'Topkapi Palace', 'palace', 41.011500, 28.983300, 'Istanbul', 'Turkey', 'The primary residence of the Ottoman sultans for nearly 400 years, now a sprawling museum complex of courtyards, the Harem, and the Imperial Treasury overlooking the Bosphorus. It houses sacred Islamic relics and jewels including the Topkapi Dagger and Spoonmaker''s Diamond.', 'It is the seat of an empire that ruled three continents and one of the most opulent palace complexes in the world.', 180, NULL, 1, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:turkey-istanbul-grand-bazaar', 'Grand Bazaar', 'market', 41.010600, 28.968100, 'Istanbul', 'Turkey', 'One of the world''s oldest and largest covered markets, dating to 1461, with more than 4,000 shops spread across 61 covered streets. Vendors sell carpets, jewelry, ceramics, lanterns, leather, and spices under painted vaulted ceilings.', 'It is the original blueprint for the indoor shopping mall and a sensory immersion in centuries-old Ottoman trade culture.', 120, NULL, 1, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:turkey-istanbul-basilica-cistern', 'Basilica Cistern', 'historic', 41.008400, 28.977900, 'Istanbul', 'Turkey', 'A vast 6th-century underground Byzantine cistern supported by 336 marble columns, including two famous Medusa-head column bases. Built under Emperor Justinian I, it once stored water for the Great Palace of Constantinople.', 'Walking through this dimly lit subterranean forest of columns feels like stepping into another world directly beneath the city.', 45, NULL, 0, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:turkey-istanbul-spice-bazaar', 'Spice Bazaar', 'market', 41.016500, 28.970600, 'Istanbul', 'Turkey', 'A 17th-century L-shaped covered market in Eminonu filled with pyramids of spices, Turkish delight, dried fruits, teas, and nuts. Originally funded by tax revenues from Egypt, it is also called the Egyptian Bazaar.', 'The smell of saffron, sumac and rose lokum hits you the moment you step in, and it is the city''s most atmospheric food market.', 60, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:turkey-istanbul-galata-tower', 'Galata Tower', 'tower', 41.025600, 28.974400, 'Istanbul', 'Turkey', 'A medieval stone tower built by the Genoese in 1348 that rises 67 meters above the Beyoglu skyline. Its top-floor observation deck offers a 360-degree panorama of the Old City, the Bosphorus, and the Golden Horn.', 'It delivers the single best classic-postcard view of Istanbul''s historic peninsula across the water.', 60, NULL, 0, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:turkey-istanbul-dolmabahce-palace', 'Dolmabahce Palace', 'palace', 41.039100, 29.000100, 'Istanbul', 'Turkey', 'A lavish 19th-century European-style Ottoman palace on the Bosphorus shoreline, blending Baroque, Rococo, and Neoclassical styles. It served as the main administrative center of the late Ottoman Empire and was where Ataturk died in 1938.', 'It shows the dramatic late-Ottoman pivot toward European grandeur, complete with a 4.5-ton crystal chandelier.', 120, NULL, 0, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:turkey-istanbul-suleymaniye-mosque', 'Suleymaniye Mosque', 'mosque', 41.016100, 28.963900, 'Istanbul', 'Turkey', 'The largest Ottoman-era mosque in Istanbul, designed by master architect Mimar Sinan and completed in 1557 for Sultan Suleiman the Magnificent. Its hilltop courtyard offers commanding views over the Golden Horn.', 'It is widely considered Sinan''s masterpiece and is far less crowded than the Blue Mosque while being arguably more impressive.', 60, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:turkey-istanbul-bosphorus-strait', 'Bosphorus Strait', 'experience', 41.109500, 29.061000, 'Istanbul', 'Turkey', 'The 31-kilometer natural strait separating Europe and Asia, lined with Ottoman palaces, wooden yali mansions, fortresses, and fishing villages. Public ferries and tour boats run cruises from Eminonu up to the Black Sea entrance.', 'A ferry ride down the Bosphorus is the only way to grasp that Istanbul is a city straddling two continents.', 120, NULL, 1, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:turkey-istanbul-chora-church', 'Chora Church', 'historic', 41.031200, 28.939400, 'Istanbul', 'Turkey', 'A small Byzantine church (Kariye) in the Edirnekapi district preserving some of the finest 14th-century Christian mosaics and frescoes in the world. It was converted to a mosque, then a museum, and recently back to a mosque.', 'Its golden mosaics rival anything in Ravenna and are an essential complement to Hagia Sophia for understanding Byzantine art.', 60, NULL, 0, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:turkey-istanbul-istiklal-avenue', 'Istiklal Avenue', 'district', 41.034400, 28.977000, 'Istanbul', 'Turkey', 'A 1.4-kilometer pedestrian boulevard running from Taksim Square to Galata, lined with 19th-century European-style buildings, cafes, bookstores, churches, and consulates. A historic red tram runs the length of the street.', 'It is the beating heart of modern Istanbul, where millions stroll each weekend amid Ottoman-era arcades and street musicians.', 90, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:united-kingdom-london-big-ben', 'Big Ben', 'landmark', 51.500700, -0.124600, 'London', 'United Kingdom', 'The Great Bell of the striking clock at the north end of the Palace of Westminster, housed in the Elizabeth Tower. The tower stands 96 metres tall and has chimed since 1859.', 'It is the single most recognizable symbol of London and the United Kingdom, framing the Thames skyline like nothing else.', 30, NULL, 1, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:united-kingdom-london-tower-of-london', 'Tower of London', 'fortress', 51.508100, -0.075900, 'London', 'United Kingdom', 'A historic castle on the north bank of the River Thames founded by William the Conqueror in 1066. It houses the Crown Jewels and has served as a royal palace, prison, and treasury.', 'Nearly a thousand years of British royal history, ravens, Beefeaters, and the dazzling Crown Jewels in one unmissable fortress.', 180, NULL, 1, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:united-kingdom-london-tower-bridge', 'Tower Bridge', 'landmark', 51.505500, -0.075400, 'London', 'United Kingdom', 'A combined bascule and suspension bridge over the River Thames, completed in 1894. Its twin Gothic-style towers and blue suspension chains make it one of London''s most photographed structures.', 'Often mistaken for London Bridge, this is the postcard bridge — and walking across it is free and unforgettable.', 45, NULL, 1, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:united-kingdom-london-buckingham-palace', 'Buckingham Palace', 'palace', 51.501400, -0.141900, 'London', 'United Kingdom', 'The London residence and administrative headquarters of the British monarch since 1837. The forecourt is the site of the famous Changing of the Guard ceremony.', 'The beating heart of the British monarchy and a mandatory stop for the iconic Changing of the Guard.', 60, NULL, 1, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:united-kingdom-london-the-british-museum', 'The British Museum', 'museum', 51.519400, -0.127000, 'London', 'United Kingdom', 'A public museum dedicated to human history, art, and culture, with a permanent collection of around eight million works. Home to the Rosetta Stone, the Parthenon Marbles, and Egyptian mummies.', 'One of the greatest collections of world artifacts ever assembled — and admission is completely free.', 180, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:united-kingdom-london-westminster-abbey', 'Westminster Abbey', 'cathedral', 51.499400, -0.127300, 'London', 'United Kingdom', 'A large, mainly Gothic abbey church and the traditional place of coronation and burial for English and British monarchs since 1066. It has hosted royal weddings including that of William and Catherine.', 'Nearly every coronation, royal wedding, and state funeral of consequence has happened inside these walls.', 90, NULL, 0, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:united-kingdom-london-london-eye', 'London Eye', 'observation_deck', 51.503300, -0.119600, 'London', 'United Kingdom', 'A 135-metre tall cantilevered observation wheel on the South Bank of the River Thames, opened in 2000. A single rotation takes about 30 minutes.', 'The best panoramic view of central London''s skyline, from Big Ben to St Paul''s, in a single slow rotation.', 45, NULL, 0, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:united-kingdom-london-hyde-park', 'Hyde Park', 'park', 51.507300, -0.165700, 'London', 'United Kingdom', 'One of London''s eight Royal Parks, covering 350 acres in central London. It contains the Serpentine lake, Speakers'' Corner, and connects to Kensington Gardens.', 'The green lung of central London — perfect for a walk, a boat on the Serpentine, or a moment of calm between landmarks.', 90, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:united-kingdom-london-st-paul-s-cathedral', 'St Paul''s Cathedral', 'cathedral', 51.513800, -0.098400, 'London', 'United Kingdom', 'An Anglican cathedral on Ludgate Hill designed by Sir Christopher Wren and completed in 1710. Its iconic dome rises 111 metres above the City of London.', 'Climb to the Whispering Gallery and the Golden Gallery for one of the most rewarding panoramic views in the city.', 90, NULL, 0, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:united-kingdom-london-borough-market', 'Borough Market', 'market', 51.505500, -0.090900, 'London', 'United Kingdom', 'A wholesale and retail food market in Southwark dating back to at least the 12th century. It hosts dozens of independent stalls selling artisanal produce, street food, and specialty goods.', 'London''s most atmospheric food market and the best single stop for tasting British and global street food under one Victorian roof.', 90, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:united-kingdom-london-the-national-gallery', 'The National Gallery', 'art_gallery', 51.508900, -0.128300, 'London', 'United Kingdom', 'An art museum in Trafalgar Square founded in 1824, housing a collection of over 2,300 paintings from the mid-13th to the 20th century. Works include masterpieces by Van Gogh, Da Vinci, Vermeer, and Turner.', 'World-class European masterpieces in the heart of Trafalgar Square, with free entry to the permanent collection.', 120, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:united-kingdom-london-covent-garden', 'Covent Garden', 'district', 51.511800, -0.122600, 'London', 'United Kingdom', 'A district in London''s West End featuring a restored 19th-century covered market, the Royal Opera House, and surrounding shopping streets. It is famous for its street performers in the central piazza.', 'The liveliest pedestrian heart of the West End, where street performers, boutique shops, and historic pubs come together.', 90, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:hong-kong-hong-kong-victoria-peak', 'Victoria Peak', 'viewpoint', 22.275900, 114.145500, 'Hong Kong', 'Hong Kong', 'The highest mountain on Hong Kong Island, offering panoramic views over the skyline, Victoria Harbour, and Kowloon. Accessible via the historic Peak Tram funicular that has operated since 1888.', 'It delivers the single most iconic view of Hong Kong''s dense skyscraper skyline against the harbour.', 120, NULL, 1, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:hong-kong-hong-kong-tian-tan-buddha', 'Tian Tan Buddha', 'religious', 22.254000, 113.905000, 'Hong Kong', 'Hong Kong', 'A 34-meter bronze seated Buddha statue completed in 1993 on Lantau Island next to Po Lin Monastery. Reached by climbing 268 steps or via the Ngong Ping 360 cable car.', 'One of the world''s largest outdoor bronze Buddha statues and a defining spiritual landmark of Lantau.', 180, NULL, 1, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:hong-kong-hong-kong-tsim-sha-tsui-promenade', 'Tsim Sha Tsui Promenade', 'viewpoint', 22.294000, 114.172200, 'Hong Kong', 'Hong Kong', 'A waterfront walkway along Kowloon''s southern tip facing Victoria Harbour and the Hong Kong Island skyline. Home to the Avenue of Stars and the nightly Symphony of Lights show.', 'It offers the best free vantage point for the harbour skyline and the world''s largest permanent light show.', 90, NULL, 1, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:hong-kong-hong-kong-star-ferry', 'Star Ferry', 'experience', 22.293500, 114.168500, 'Hong Kong', 'Hong Kong', 'A historic passenger ferry service operating across Victoria Harbour between Tsim Sha Tsui and Central/Wan Chai since 1888. Still one of the cheapest harbour crossings in the world.', 'A 10-minute ride on this 130-year-old ferry is the classic, postcard-perfect way to cross Victoria Harbour.', 30, NULL, 1, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:hong-kong-hong-kong-wong-tai-sin-temple', 'Wong Tai Sin Temple', 'temple', 22.342400, 114.193400, 'Hong Kong', 'Hong Kong', 'A colorful Taoist temple in Kowloon founded in 1921 and dedicated to the deity Wong Tai Sin. Famous for fortune-telling and ''kau cim'' bamboo stick divination.', 'It is Hong Kong''s most popular working temple and a vibrant window into Cantonese folk religion.', 60, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:hong-kong-hong-kong-temple-street-night-market', 'Temple Street Night Market', 'market', 22.307200, 114.170600, 'Hong Kong', 'Hong Kong', 'A bustling open-air night market running along Temple Street in Yau Ma Tei and Jordan. Known for street food, fortune tellers, Cantonese opera performers, and bargain stalls.', 'It is the quintessential Hong Kong night-market experience captured in countless films.', 90, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:hong-kong-hong-kong-hong-kong-disneyland', 'Hong Kong Disneyland', 'theme_park', 22.313000, 114.041400, 'Hong Kong', 'Hong Kong', 'A Disney-themed amusement park on Lantau Island that opened in 2005. Features seven themed lands including Adventureland, Tomorrowland, and the World of Frozen.', 'It is Asia''s most accessible Disney park and a top family destination in the region.', 480, NULL, 0, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:hong-kong-hong-kong-ngong-ping-360', 'Ngong Ping 360', 'experience', 22.289500, 113.943000, 'Hong Kong', 'Hong Kong', 'A 5.7-kilometer cable car system connecting Tung Chung to Ngong Ping village on Lantau Island. The ride offers sweeping views of the South China Sea, the airport, and mountainous Lantau.', 'The 25-minute glass-bottom cabin ride is one of Asia''s most scenic cable car journeys.', 90, NULL, 0, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:hong-kong-hong-kong-man-mo-temple', 'Man Mo Temple', 'temple', 22.284000, 114.150000, 'Hong Kong', 'Hong Kong', 'A historic temple in Sheung Wan built in 1847 and dedicated to the gods of literature (Man) and war (Mo). Famous for its huge hanging incense coils that fill the hall with smoke.', 'It is one of Hong Kong''s oldest temples and a striking time capsule of colonial-era Chinese worship.', 30, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:hong-kong-hong-kong-hong-kong-museum-of-history', 'Hong Kong Museum of History', 'museum', 22.301500, 114.177200, 'Hong Kong', 'Hong Kong', 'A major museum in Tsim Sha Tsui East telling the story of Hong Kong from prehistory through the handover. Best known for its ''Hong Kong Story'' permanent exhibition.', 'It offers the clearest, most engaging overview of how Hong Kong became what it is today.', 150, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:hong-kong-hong-kong-hong-kong-park', 'Hong Kong Park', 'park', 22.277400, 114.162000, 'Hong Kong', 'Hong Kong', 'An 8-hectare urban park in Central opened in 1991, built on the site of the former Victoria Barracks. Features a large walk-through aviary, a conservatory, and the historic Flagstaff House Museum of Tea Ware.', 'It is a free, lush green refuge tucked between the skyscrapers of Central and Admiralty.', 60, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:hong-kong-hong-kong-lan-kwai-fong', 'Lan Kwai Fong', 'district', 22.281100, 114.155600, 'Hong Kong', 'Hong Kong', 'A small, sloping square of streets in Central packed with bars, restaurants, and clubs. The center of Hong Kong''s expat and weekend nightlife scene since the 1980s.', 'It is the city''s iconic nightlife district, essential for experiencing Hong Kong after dark.', 90, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:united-arab-emirates-dubai-burj-khalifa', 'Burj Khalifa', 'tower', 25.197200, 55.274400, 'Dubai', 'United Arab Emirates', 'The world''s tallest building at 828 meters, completed in 2010, with observation decks on the 124th, 125th, and 148th floors. It anchors the Downtown Dubai district and is the centerpiece of the city''s skyline.', 'Standing atop the tallest structure ever built is a once-in-a-lifetime view you simply cannot get anywhere else on Earth.', 120, NULL, 1, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:united-arab-emirates-dubai-the-dubai-mall', 'The Dubai Mall', 'district', 25.197200, 55.279600, 'Dubai', 'United Arab Emirates', 'One of the largest shopping and entertainment complexes in the world, containing over 1,200 stores, the Dubai Aquarium, an Olympic-size ice rink, and direct access to the Burj Khalifa. It is the city''s social and tourist epicenter.', 'It is the beating heart of modern Dubai where shopping, entertainment, and the Dubai Fountain show all converge.', 180, NULL, 1, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:united-arab-emirates-dubai-the-dubai-fountain', 'The Dubai Fountain', 'landmark', 25.195600, 55.274300, 'Dubai', 'United Arab Emirates', 'The world''s largest choreographed fountain system, set on the 30-acre Burj Khalifa Lake. It performs water, light, and music shows every 30 minutes in the evenings.', 'Its free, dramatic nightly performances at the foot of the Burj Khalifa are an essential Dubai experience.', 30, NULL, 1, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:united-arab-emirates-dubai-palm-jumeirah', 'Palm Jumeirah', 'landmark', 25.112400, 55.139000, 'Dubai', 'United Arab Emirates', 'A massive artificial archipelago shaped like a palm tree, built from reclaimed land and home to luxury hotels, residences, and the Atlantis resort. It is one of the most ambitious engineering projects ever undertaken.', 'Visiting an island shaped like a palm tree that is visible from space is uniquely Dubai.', 120, NULL, 1, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:united-arab-emirates-dubai-burj-al-arab', 'Burj Al Arab', 'landmark', 25.141300, 55.185300, 'Dubai', 'United Arab Emirates', 'An iconic sail-shaped luxury hotel standing 321 meters tall on its own artificial island, opened in 1999. It is one of the most photographed buildings in the world and a defining symbol of Dubai.', 'Its instantly recognizable silhouette is the architectural emblem of modern Dubai.', 45, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:united-arab-emirates-dubai-dubai-marina', 'Dubai Marina', 'district', 25.080500, 55.140300, 'Dubai', 'United Arab Emirates', 'A 3-kilometer man-made canal district lined with skyscrapers, restaurants, and a waterfront promenade called the Marina Walk. It is one of the world''s largest man-made marinas.', 'Strolling the promenade beneath glittering towers and dining canalside captures contemporary Dubai life.', 90, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:united-arab-emirates-dubai-gold-souk', 'Gold Souk', 'market', 25.269700, 55.297800, 'Dubai', 'United Arab Emirates', 'A traditional market in the Deira district featuring hundreds of retailers selling gold, silver, and precious gemstones. It is one of the largest gold markets in the world.', 'The dazzling shop windows and centuries-old trading culture offer a glimpse of old Dubai before the skyscrapers.', 60, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:united-arab-emirates-dubai-al-fahidi-historical-neighbourhood', 'Al Fahidi Historical Neighbourhood', 'historic', 25.263700, 55.300800, 'Dubai', 'United Arab Emirates', 'One of the oldest residential areas in Dubai, featuring traditional wind-tower architecture, narrow lanes, art galleries, and the Dubai Museum at Al Fahidi Fort. It dates back to the 1890s.', 'It is the best-preserved glimpse of pre-oil Dubai and essential context for understanding the city''s transformation.', 90, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:united-arab-emirates-dubai-jumeirah-mosque', 'Jumeirah Mosque', 'mosque', 25.235100, 55.265500, 'Dubai', 'United Arab Emirates', 'A stunning example of modern Islamic architecture built in the traditional Fatimid style, and one of the few mosques in Dubai open to non-Muslim visitors via guided tours. It opened in 1979.', 'It is the most accessible place for international visitors to learn about Emirati culture and Islam firsthand.', 75, NULL, 0, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:united-arab-emirates-dubai-dubai-creek', 'Dubai Creek', 'river', 25.263100, 55.297200, 'Dubai', 'United Arab Emirates', 'A natural saltwater inlet that historically divided the city into Deira and Bur Dubai, traversed by traditional wooden abra water taxis. It was the original heart of Dubai''s pearling and trading economy.', 'A 1-dirham abra ride across the creek is the cheapest and most authentic experience of old Dubai.', 45, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:united-arab-emirates-dubai-museum-of-the-future', 'Museum of the Future', 'museum', 25.224700, 55.282600, 'Dubai', 'United Arab Emirates', 'A striking torus-shaped building covered in Arabic calligraphy, opened in 2022, housing immersive exhibits on space, ecology, and emerging technology. National Geographic named it one of the most beautiful buildings on Earth.', 'Both the architecture and the futuristic exhibits are unlike anything else in the world.', 150, NULL, 0, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:united-arab-emirates-dubai-jumeirah-public-beach', 'Jumeirah Public Beach', 'beach', 25.204800, 55.242500, 'Dubai', 'United Arab Emirates', 'A long stretch of free public beach along the Arabian Gulf with views of the Burj Al Arab and the Dubai skyline. It features soft white sand and clear warm waters.', 'It offers the iconic Burj Al Arab photo backdrop and a free taste of Dubai''s coastal lifestyle.', 90, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:singapore-singapore-marina-bay-sands', 'Marina Bay Sands', 'landmark', 1.283400, 103.860700, 'Singapore', 'Singapore', 'An iconic integrated resort with three 55-story hotel towers connected by the SkyPark, a cantilevered rooftop platform featuring an infinity pool and observation deck. It also houses a casino, luxury shopping mall, and convention center.', 'Its boat-on-towers silhouette has become the defining symbol of modern Singapore''s skyline.', 120, NULL, 1, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:singapore-singapore-gardens-by-the-bay', 'Gardens by the Bay', 'garden', 1.281600, 103.863600, 'Singapore', 'Singapore', 'A 101-hectare nature park featuring the iconic Supertree Grove vertical gardens and two cooled conservatories, the Flower Dome and Cloud Forest. The outdoor gardens and Supertree Grove are free to walk through.', 'The futuristic Supertrees and nightly light show are a uniquely Singaporean spectacle unlike anywhere else on Earth.', 180, NULL, 1, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:singapore-singapore-merlion-park', 'Merlion Park', 'landmark', 1.286800, 103.854500, 'Singapore', 'Singapore', 'A waterfront park along Marina Bay home to the 8.6-meter-tall Merlion statue, a mythical creature with a lion''s head and fish''s body that serves as Singapore''s national personification. The statue spouts water into the bay.', 'Posing with the Merlion is the quintessential Singapore tourist photo opportunity, with a postcard view of the Marina Bay skyline behind it.', 30, NULL, 1, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:singapore-singapore-singapore-botanic-gardens', 'Singapore Botanic Gardens', 'garden', 1.313800, 103.815900, 'Singapore', 'Singapore', 'A 160-year-old tropical garden and UNESCO World Heritage Site spanning 82 hectares, featuring rainforest, themed gardens, and lakes. The famous National Orchid Garden within charges a small fee.', 'It''s Singapore''s only UNESCO site, a verdant escape rich with heritage trees and one of the world''s finest orchid collections.', 150, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:singapore-singapore-sentosa-island', 'Sentosa Island', 'district', 1.249400, 103.830300, 'Singapore', 'Singapore', 'A resort island off Singapore''s southern coast home to beaches, theme parks including Universal Studios Singapore, S.E.A. Aquarium, hotels, and a cable car. Entry to the island is essentially free; individual attractions are ticketed.', 'It packs Singapore''s biggest concentration of family attractions, beaches, and entertainment into a single accessible island.', 360, NULL, 1, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:singapore-singapore-chinatown-singapore', 'Chinatown Singapore', 'district', 1.281200, 103.844800, 'Singapore', 'Singapore', 'A historic ethnic enclave centered around Pagoda Street and Smith Street, filled with shophouses, temples, hawker centers, and markets. Home to the Buddha Tooth Relic Temple and Sri Mariamman Temple.', 'It''s the cultural heart of Chinese Singapore, where heritage shophouses, street food, and red lanterns capture the city''s multicultural roots.', 120, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:singapore-singapore-little-india', 'Little India', 'district', 1.306600, 103.849700, 'Singapore', 'Singapore', 'A vibrant historic district along Serangoon Road filled with colorful shophouses, sari shops, spice stores, Hindu temples, and the bustling Tekka Centre wet market. Home to the colorful Sri Veeramakaliamman Temple.', 'It''s the most sensorily rich and authentic ethnic quarter in Singapore, offering an instant immersion in South Indian culture.', 90, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:singapore-singapore-sri-mariamman-temple', 'Sri Mariamman Temple', 'temple', 1.281900, 103.845100, 'Singapore', 'Singapore', 'Singapore''s oldest Hindu temple, founded in 1827 and dedicated to the goddess Mariamman. Located in Chinatown, it''s famous for its elaborately sculpted gopuram (entrance tower) covered in colorful deities.', 'Its ornate Dravidian gopuram is one of Singapore''s most photographed religious facades and a National Monument.', 30, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:singapore-singapore-sultan-mosque', 'Sultan Mosque', 'mosque', 1.302400, 103.859300, 'Singapore', 'Singapore', 'Singapore''s most important mosque, originally built in 1824 for the first sultan of Singapore and rebuilt in 1932 with a massive golden dome. It sits at the heart of the historic Kampong Glam Malay-Muslim quarter.', 'Its golden dome and Indo-Saracenic architecture anchor the colorful Kampong Glam district, one of Singapore''s most atmospheric neighborhoods.', 45, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:singapore-singapore-raffles-hotel-singapore', 'Raffles Hotel Singapore', 'historic', 1.294900, 103.854500, 'Singapore', 'Singapore', 'A legendary colonial-style luxury hotel opened in 1887, famous as the birthplace of the Singapore Sling cocktail at its Long Bar. The all-suite property is a National Monument with whitewashed verandas and tropical courtyards.', 'It''s a living relic of British colonial Singapore and the iconic spot to sip a Singapore Sling at its original Long Bar.', 60, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:singapore-singapore-singapore-zoo', 'Singapore Zoo', 'zoo', 1.404300, 103.793000, 'Singapore', 'Singapore', 'A 28-hectare open-concept rainforest zoo opened in 1973, famous for its naturalistic exhibits without bars and over 2,800 animals. Part of the Mandai Wildlife Reserve, alongside Night Safari and River Wonders.', 'Consistently ranked among the world''s best zoos, its open enclosures let you get remarkably close to orangutans and other wildlife.', 240, NULL, 0, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:singapore-singapore-buddha-tooth-relic-temple', 'Buddha Tooth Relic Temple', 'temple', 1.281500, 103.844300, 'Singapore', 'Singapore', 'A large four-story Tang-dynasty-styled Buddhist temple and museum in Chinatown, completed in 2007. It houses what is believed to be a tooth relic of the Buddha in a 320-kilogram gold stupa on the fourth floor.', 'Its grand Tang-style architecture and ornate prayer hall make it one of the most visually stunning religious buildings in Chinatown.', 60, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:malaysia-kuala-lumpur-petronas-twin-towers', 'Petronas Twin Towers', 'tower', 3.157900, 101.711400, 'Kuala Lumpur', 'Malaysia', 'Twin 88-story skyscrapers standing 452 meters tall, connected by a double-decker skybridge on the 41st and 42nd floors. They were the world''s tallest buildings from 1998 to 2004 and remain the tallest twin towers on Earth.', 'The defining symbol of modern Kuala Lumpur and one of the most recognizable skyscraper silhouettes in the world.', 120, NULL, 1, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:malaysia-kuala-lumpur-batu-caves', 'Batu Caves', 'religious', 3.237900, 101.684000, 'Kuala Lumpur', 'Malaysia', 'A 400-million-year-old limestone hill containing a series of caves and Hindu temples, fronted by a 42.7-meter golden statue of Lord Murugan and 272 rainbow-painted steps. It is one of the most popular Hindu shrines outside India.', 'The combination of the giant gold statue, the colorful staircase, and the cathedral-sized cave temple is unlike anywhere else in Asia.', 120, NULL, 1, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:malaysia-kuala-lumpur-kl-tower', 'KL Tower', 'observation_deck', 3.152800, 101.703800, 'Kuala Lumpur', 'Malaysia', 'A 421-meter telecommunications tower with an observation deck and open-air Sky Box jutting from the side. It is the seventh-tallest freestanding tower in the world.', 'Offers the best 360-degree view of Kuala Lumpur because, unlike the Petronas Towers, you can actually see the Petronas Towers from it.', 90, NULL, 1, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:malaysia-kuala-lumpur-merdeka-square', 'Merdeka Square', 'square', 3.147800, 101.693500, 'Kuala Lumpur', 'Malaysia', 'The historic plaza where Malaysian independence was declared on August 31, 1957, anchored by one of the world''s tallest flagpoles at 95 meters. It is flanked by the Moorish-style Sultan Abdul Samad Building.', 'The birthplace of modern Malaysia and the city''s most photogenic colonial-era ensemble.', 45, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:malaysia-kuala-lumpur-sultan-abdul-samad-building', 'Sultan Abdul Samad Building', 'historic', 3.148900, 101.694300, 'Kuala Lumpur', 'Malaysia', 'A late-19th-century Moorish-revival landmark with a 41-meter clock tower and copper domes, built in 1897 to house British colonial administration. It now houses government offices.', 'Kuala Lumpur''s most beautiful colonial building and the postcard backdrop of Merdeka Square.', 30, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:malaysia-kuala-lumpur-masjid-negara', 'Masjid Negara', 'mosque', 3.141900, 101.691700, 'Kuala Lumpur', 'Malaysia', 'Malaysia''s National Mosque, completed in 1965, with a distinctive 73-meter minaret and an 18-pointed star-shaped concrete roof inspired by an open umbrella. It accommodates 15,000 worshippers.', 'A bold modernist take on Islamic architecture and one of Southeast Asia''s most striking mosques, open to non-Muslim visitors outside prayer times.', 60, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:malaysia-kuala-lumpur-thean-hou-temple', 'Thean Hou Temple', 'temple', 3.119200, 101.687800, 'Kuala Lumpur', 'Malaysia', 'A six-tiered Chinese temple completed in 1989, dedicated to the sea goddess Mazu (Tian Hou) and perched on Robson Heights. It is one of the largest and oldest-style Chinese temples in Southeast Asia.', 'The sweeping red-and-gold pagoda layered with hundreds of lanterns is one of KL''s most photogenic spots, especially at dusk.', 60, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:malaysia-kuala-lumpur-sri-mahamariamman-temple', 'Sri Mahamariamman Temple', 'temple', 3.143800, 101.696700, 'Kuala Lumpur', 'Malaysia', 'The oldest Hindu temple in Kuala Lumpur, founded in 1873, featuring an ornate 22.9-meter gopuram tower densely sculpted with 228 Hindu deities. It sits on the edge of Chinatown.', 'A vivid 19th-century South Indian temple in the heart of old KL and the starting point of the annual Thaipusam procession to Batu Caves.', 30, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:malaysia-kuala-lumpur-petaling-street', 'Petaling Street', 'market', 3.143800, 101.698200, 'Kuala Lumpur', 'Malaysia', 'The main street of Kuala Lumpur''s Chinatown, covered by a green roof and lined with stalls selling street food, knockoff goods, and souvenirs. It traces back to the late 1800s tin-mining era.', 'The most atmospheric old-school market street in the city and one of the best places to graze on hawker food.', 90, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:malaysia-kuala-lumpur-klcc-park', 'KLCC Park', 'park', 3.157000, 101.713700, 'Kuala Lumpur', 'Malaysia', 'A 50-acre landscaped park at the foot of the Petronas Twin Towers, designed by Brazilian architect Roberto Burle Marx and home to a Lake Symphony fountain show. It includes jogging paths, a children''s playground, and a wading pool.', 'Offers the iconic ground-level view of the Twin Towers and the nightly choreographed fountain show, all for free.', 60, NULL, 1, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:malaysia-kuala-lumpur-perdana-botanical-gardens', 'Perdana Botanical Gardens', 'garden', 3.143000, 101.685000, 'Kuala Lumpur', 'Malaysia', 'Kuala Lumpur''s oldest public garden, established in 1888 as Lake Gardens, sprawling across 92 hectares of lawns, lakes, and themed parks including the KL Bird Park and Butterfly Park. It sits in the colonial-era heart of the city.', 'The green lung of central KL and home to the world''s largest free-flight walk-in aviary.', 120, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:malaysia-kuala-lumpur-islamic-arts-museum-malaysia', 'Islamic Arts Museum Malaysia', 'museum', 3.141900, 101.688600, 'Kuala Lumpur', 'Malaysia', 'A museum opened in 1998 housing over 7,000 artifacts of Islamic art including Qurans, ceramics, textiles, and architectural models, beneath inverted Persian-style domes. It is the largest museum of Islamic art in Southeast Asia.', 'Widely regarded as one of the finest Islamic art collections in the world, with stunning architecture to match.', 150, NULL, 0, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:malaysia-kuala-lumpur-central-market-kuala-lumpur', 'Central Market Kuala Lumpur', 'market', 3.145300, 101.696000, 'Kuala Lumpur', 'Malaysia', 'An Art Deco landmark built in 1888 as a wet market and converted in the 1980s into a craft and culture bazaar. It now houses batik, handicrafts, and food stalls representing Malaysia''s ethnic groups.', 'The best one-stop shop for Malaysian crafts and souvenirs, set in a protected heritage building.', 75, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:united-states-new-york-city-statue-of-liberty', 'Statue of Liberty', 'monument', 40.689200, -74.044500, 'New York City', 'United States', 'A 151-foot copper neoclassical sculpture on Liberty Island, gifted by France in 1886. It stands as a symbol of freedom and welcomed millions of immigrants arriving by sea.', 'The single most recognizable symbol of America and one of the most iconic monuments on Earth.', 180, NULL, 1, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:united-states-new-york-city-central-park', 'Central Park', 'park', 40.782900, -73.965400, 'New York City', 'United States', 'An 843-acre urban park in the middle of Manhattan, designed by Frederick Law Olmsted and Calvert Vaux and opened in 1858. It contains lakes, meadows, woodlands, the Bethesda Terrace, and the Bow Bridge.', 'The green heart of Manhattan and arguably the most famous urban park in the world.', 150, NULL, 1, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:united-states-new-york-city-times-square', 'Times Square', 'square', 40.758000, -73.985500, 'New York City', 'United States', 'A major commercial intersection and entertainment hub at Broadway and Seventh Avenue, famous for its dazzling LED billboards and Broadway theaters. It is the site of the annual New Year''s Eve ball drop.', 'The neon-drenched crossroads of the world and a quintessential first-time New York experience.', 60, NULL, 1, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:united-states-new-york-city-empire-state-building', 'Empire State Building', 'observation_deck', 40.748400, -73.985700, 'New York City', 'United States', 'A 102-story Art Deco skyscraper completed in 1931, standing 1,454 feet tall in Midtown Manhattan. Its 86th and 102nd floor observatories offer panoramic views of the city.', 'The defining skyscraper of the New York skyline and a global Art Deco icon.', 120, NULL, 1, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:united-states-new-york-city-brooklyn-bridge', 'Brooklyn Bridge', 'landmark', 40.706100, -73.996900, 'New York City', 'United States', 'A hybrid cable-stayed/suspension bridge completed in 1883, connecting Manhattan and Brooklyn across the East River. Its elevated wooden pedestrian promenade offers sweeping views of the harbor and skyline.', 'An engineering masterpiece and a free walk that delivers postcard views of Lower Manhattan.', 60, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:united-states-new-york-city-the-metropolitan-museum-of-art', 'The Metropolitan Museum of Art', 'museum', 40.779400, -73.963200, 'New York City', 'United States', 'The largest art museum in the Americas, founded in 1870 and located on Fifth Avenue along Central Park. Its collection of over two million works spans 5,000 years of human creativity.', 'One of the world''s greatest encyclopedic museums, comparable to the Louvre or British Museum.', 180, NULL, 0, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:united-states-new-york-city-rockefeller-center', 'Rockefeller Center', 'landmark', 40.758700, -73.978700, 'New York City', 'United States', 'A 22-acre Art Deco complex of 19 commercial buildings built by the Rockefeller family in the 1930s. It houses the Top of the Rock observation deck, NBC Studios, Radio City Music Hall, and the famous winter ice rink and Christmas tree.', 'A landmark complex offering the only Manhattan skyline view that includes the Empire State Building itself.', 90, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:united-states-new-york-city-9-11-memorial-museum', '9/11 Memorial & Museum', 'monument', 40.711500, -74.013400, 'New York City', 'United States', 'A memorial plaza featuring twin reflecting pools set in the footprints of the original World Trade Center towers, with the names of the 2,977 victims inscribed in bronze. The adjacent museum tells the story of September 11, 2001.', 'The most moving and historically significant modern memorial in the United States.', 120, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:united-states-new-york-city-american-museum-of-natural-history', 'American Museum of Natural History', 'museum', 40.781300, -73.974000, 'New York City', 'United States', 'One of the world''s largest natural history museums, founded in 1869 on the Upper West Side. It features massive dinosaur halls, the Rose Center for Earth and Space, and dioramas of global ecosystems.', 'An unmissable family-friendly institution famed for its blue whale, T. rex, and Hayden Planetarium.', 180, NULL, 0, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:united-states-new-york-city-grand-central-terminal', 'Grand Central Terminal', 'landmark', 40.752700, -73.977200, 'New York City', 'United States', 'A Beaux-Arts commuter rail terminal opened in 1913, featuring a vast main concourse with a celestial-mural ceiling, marble staircases, and the iconic four-faced brass clock. It serves Metro-North Railroad.', 'One of the most beautiful and photographed train stations in the world, free to wander.', 45, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:united-states-new-york-city-high-line', 'High Line', 'park', 40.748000, -74.004800, 'New York City', 'United States', 'A 1.45-mile elevated linear park built on a former New York Central Railroad spur on Manhattan''s West Side. It runs from Gansevoort Street in the Meatpacking District up to 34th Street through Chelsea.', 'A unique elevated walk through gardens, public art, and skyline views, free to enjoy.', 90, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:united-states-new-york-city-st-patrick-s-cathedral', 'St. Patrick''s Cathedral', 'cathedral', 40.758500, -73.975900, 'New York City', 'United States', 'A Neo-Gothic Roman Catholic cathedral completed in 1878, located on Fifth Avenue opposite Rockefeller Center. It is the seat of the Archbishop of New York and features twin 330-foot spires.', 'The most prominent Gothic cathedral in the United States, free to enter and visually stunning.', 30, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:france-paris-eiffel-tower', 'Eiffel Tower', 'tower', 48.858400, 2.294500, 'Paris', 'France', 'A 330-meter wrought-iron lattice tower on the Champ de Mars, built by Gustave Eiffel for the 1889 World''s Fair. It has three visitor levels reachable by stairs or elevator, with restaurants and observation decks.', 'It is the single most recognizable symbol of Paris and France, and seeing it in person — especially when it sparkles at night — is the defining Paris moment.', 150, NULL, 1, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:france-paris-louvre-museum', 'Louvre Museum', 'museum', 48.860600, 2.337600, 'Paris', 'France', 'The world''s most-visited museum, housed in a former royal palace with I. M. Pei''s glass pyramid at its entrance. Its collection spans 35,000 works including the Mona Lisa, Venus de Milo, and Winged Victory of Samothrace.', 'It holds the greatest concentration of Western art masterpieces on earth, and the Mona Lisa alone draws millions who want to say they have seen her.', 240, NULL, 1, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:france-paris-notre-dame-cathedral', 'Notre-Dame Cathedral', 'cathedral', 48.853000, 2.349900, 'Paris', 'France', 'A 12th-century French Gothic cathedral on the Ile de la Cite, famous for its flying buttresses, rose windows, and gargoyles. It reopened in December 2024 after restoration following the 2019 fire.', 'It is the spiritual and geographic heart of Paris (kilometer zero of France is on its plaza) and its newly restored interior is a once-in-a-generation sight.', 60, NULL, 1, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:france-paris-arc-de-triomphe', 'Arc de Triomphe', 'monument', 48.873800, 2.295000, 'Paris', 'France', 'A 50-meter neoclassical triumphal arch commissioned by Napoleon in 1806 to honor French military victories, anchoring the western end of the Champs-Elysees. Its rooftop terrace offers panoramic views down twelve radiating avenues.', 'It is the ceremonial heart of Paris and arguably the city''s best rooftop view, with the Eiffel Tower and Champs-Elysees framed perfectly from above.', 75, NULL, 1, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:france-paris-sacre-coeur-basilica', 'Sacre-Coeur Basilica', 'cathedral', 48.886700, 2.343100, 'Paris', 'France', 'A white Romano-Byzantine basilica completed in 1914, perched atop Montmartre, the highest point in Paris. Its dome and forecourt deliver a sweeping view across the entire city.', 'Free entry, an unmatched free panorama of Paris, and the bohemian Montmartre village around it make this a non-negotiable stop.', 90, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:france-paris-musee-d-orsay', 'Musee d''Orsay', 'museum', 48.860000, 2.326600, 'Paris', 'France', 'A museum housed in the grand Beaux-Arts Gare d''Orsay railway station, holding the world''s largest collection of Impressionist and Post-Impressionist masterpieces. Artists represented include Monet, Renoir, Degas, Van Gogh, Cezanne, and Gauguin.', 'If the Louvre is for old masters, Orsay is for the Impressionists who defined modern Paris, and the giant station clock window is a photo icon in its own right.', 150, NULL, 0, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:france-paris-palace-of-versailles', 'Palace of Versailles', 'palace', 48.804900, 2.120400, 'Paris', 'France', 'The opulent former royal residence of Louis XIV through Louis XVI, located about 20 km southwest of central Paris. It features the Hall of Mirrors, royal apartments, and 800 hectares of formal French gardens.', 'It is the definitive symbol of absolute monarchy and Baroque excess, and the Hall of Mirrors is one of the most breathtaking interiors in Europe.', 300, NULL, 0, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:france-paris-sainte-chapelle', 'Sainte-Chapelle', 'cathedral', 48.855400, 2.345000, 'Paris', 'France', 'A 13th-century royal Gothic chapel built by King Louis IX to house Christ''s Crown of Thorns, hidden inside the Palais de Justice complex. Its upper chapel contains 15 stained-glass windows depicting over 1,100 biblical scenes.', 'On a sunny day the stained glass turns the chapel into a kaleidoscope — widely considered the most beautiful interior in Paris.', 60, NULL, 0, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:france-paris-luxembourg-gardens', 'Luxembourg Gardens', 'garden', 48.846200, 2.337200, 'Paris', 'France', 'A 23-hectare formal garden created in 1612 by Marie de'' Medici beside the Luxembourg Palace, now the seat of the French Senate. It features the Medici Fountain, tree-lined allees, and the iconic green sailboat pond.', 'It is where Parisians actually relax, and watching children sail rented wooden boats on the pond is the most quintessentially Parisian afternoon you can have for free.', 90, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:france-paris-champs-elysees', 'Champs-Elysees', 'district', 48.869800, 2.307900, 'Paris', 'France', 'A 1.9-km tree-lined avenue running from Place de la Concorde to the Arc de Triomphe, lined with flagship stores, cafes, and theatres. It hosts the Bastille Day parade and the final stage of the Tour de France.', 'Often called ''the world''s most beautiful avenue,'' a stroll up it to the Arc is a rite of passage for every first-time visitor.', 75, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:france-paris-centre-pompidou', 'Centre Pompidou', 'art_gallery', 48.860700, 2.352200, 'Paris', 'France', 'A radical inside-out high-tech building completed in 1977, with its plumbing, ducts, and escalators exposed on the exterior. It houses the Musee National d''Art Moderne, the largest modern art museum in Europe.', 'It is Paris''s bold counterpoint to its classical beauty, and the rooftop view from the exterior escalator is one of the city''s best.', 150, NULL, 0, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:france-paris-place-de-la-concorde', 'Place de la Concorde', 'square', 48.865600, 2.321100, 'Paris', 'France', 'The largest public square in Paris, sitting between the Tuileries Garden and the Champs-Elysees. At its center stands the 3,300-year-old Luxor Obelisk, a gift from Egypt installed in 1836.', 'This is where Louis XVI and Marie Antoinette were guillotined, and today it offers one of the best free sightlines in Paris — Eiffel Tower, Arc de Triomphe, and Madeleine all visible at once.', 30, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:japan-tokyo-senso-ji-temple', 'Senso-ji Temple', 'temple', 35.714800, 139.796700, 'Tokyo', 'Japan', 'Tokyo''s oldest Buddhist temple, founded in 645 AD and dedicated to Kannon, the goddess of mercy. The approach features the iconic Kaminarimon (Thunder Gate) with its giant red lantern and the Nakamise shopping street.', 'It''s the spiritual and historic heart of old Tokyo and the city''s single most photographed landmark.', 90, NULL, 1, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:japan-tokyo-meiji-jingu', 'Meiji Jingu', 'shrine', 35.676400, 139.699300, 'Tokyo', 'Japan', 'A Shinto shrine completed in 1920 dedicated to Emperor Meiji and Empress Shoken, set within a 170-acre forest of 100,000 donated trees in central Tokyo. The grand torii gates and quiet wooded paths offer a striking contrast to the surrounding city.', 'It''s the most important Shinto shrine in Tokyo and a tranquil green oasis steps from Harajuku.', 75, NULL, 1, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:japan-tokyo-shibuya-crossing', 'Shibuya Crossing', 'landmark', 35.659500, 139.700400, 'Tokyo', 'Japan', 'The world''s busiest pedestrian intersection, located outside Shibuya Station, where thousands of people cross from all directions every light change. It is surrounded by giant video screens and neon advertising that define the modern Tokyo skyline.', 'It''s the definitive symbol of Tokyo''s organized chaos and modern urban energy.', 30, NULL, 1, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:japan-tokyo-tokyo-skytree', 'Tokyo Skytree', 'tower', 35.710100, 139.810700, 'Tokyo', 'Japan', 'At 634 meters, the tallest tower in Japan and the second-tallest structure in the world, completed in 2012 in the Sumida district. It has two observation decks offering panoramic views of the entire Kanto region, with Mount Fuji visible on clear days.', 'It''s the highest vantage point in Tokyo and the best place to grasp the scale of the world''s largest metropolitan area.', 120, NULL, 1, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:japan-tokyo-tokyo-tower', 'Tokyo Tower', 'tower', 35.658600, 139.745400, 'Tokyo', 'Japan', 'A 333-meter red-and-white communications tower in Minato, built in 1958 and inspired by the Eiffel Tower. It remains a beloved symbol of postwar Tokyo''s recovery and offers observation decks over the central city.', 'It''s the nostalgic icon featured in countless films and anime, and visually defines the Tokyo skyline.', 90, NULL, 0, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:japan-tokyo-tsukiji-outer-market', 'Tsukiji Outer Market', 'market', 35.665400, 139.770700, 'Tokyo', 'Japan', 'A dense warren of streets lined with around 400 small shops, food stalls, and restaurants serving the freshest sushi, tamagoyaki, and seafood in Tokyo. While the famous tuna auction moved to Toyosu in 2018, the outer market remains fully operational.', 'It''s the best place in Tokyo to eat your way through Japanese seafood culture in a single morning.', 120, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:japan-tokyo-shinjuku-gyoen-national-garden', 'Shinjuku Gyoen National Garden', 'garden', 35.685200, 139.710000, 'Tokyo', 'Japan', 'A 144-acre landscape garden in central Tokyo blending Japanese traditional, French formal, and English landscape styles, originally an imperial garden opened to the public in 1949. It is one of Tokyo''s premier cherry blossom viewing locations.', 'It''s the most beautiful and varied garden in central Tokyo, especially during sakura season.', 90, NULL, 0, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:japan-tokyo-imperial-palace', 'Imperial Palace', 'palace', 35.685200, 139.752800, 'Tokyo', 'Japan', 'The primary residence of the Emperor of Japan, sitting on the former site of Edo Castle in the center of Tokyo and surrounded by stone walls and moats. The East Gardens are open to the public and contain ruins of the original castle keep.', 'It''s the symbolic center of Japan and home to a 1,000-year-old monarchy.', 90, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:japan-tokyo-akihabara', 'Akihabara', 'district', 35.702200, 139.774500, 'Tokyo', 'Japan', 'Tokyo''s electronics and otaku culture district, packed with multi-story stores selling anime, manga, video games, and electronics, along with maid cafes and arcades. The area has been the center of Japanese gadget culture since the postwar era.', 'It''s the global epicenter of anime, gaming, and Japanese pop culture.', 120, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:japan-tokyo-ueno-park', 'Ueno Park', 'park', 35.715600, 139.773100, 'Tokyo', 'Japan', 'A large public park established in 1873 containing the Tokyo National Museum, Ueno Zoo, several other major museums, and Shinobazu Pond. It is one of Tokyo''s most famous cherry blossom destinations with over 1,000 sakura trees.', 'It packs Tokyo''s top museums, a historic zoo, and seasonal beauty into one walkable area.', 120, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:japan-tokyo-teamlab-planets-tokyo', 'teamLab Planets TOKYO', 'art_gallery', 35.649200, 139.790300, 'Tokyo', 'Japan', 'An immersive digital art museum in Toyosu where visitors walk barefoot through water, mirrored rooms, and infinite floral installations. Created by the art collective teamLab, it is one of the most visited single-artist museums in the world.', 'It''s a uniquely Tokyo sensory experience that has redefined what a museum can be.', 120, NULL, 0, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:japan-tokyo-ginza', 'Ginza', 'district', 35.671700, 139.765000, 'Tokyo', 'Japan', 'Tokyo''s premier upscale shopping and dining district, lined with flagship department stores, luxury boutiques, art galleries, and historic Kabuki theater. On weekends the main avenue closes to cars and becomes a pedestrian promenade.', 'It''s the most elegant district in Tokyo and showcases the city''s refined commercial culture.', 90, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:turkey-antalya-hadrian-s-gate', 'Hadrian''s Gate', 'monument', 36.887000, 30.708000, 'Antalya', 'Turkey', 'A triumphal triple-arched marble gate built in 130 AD to honor the visit of Roman Emperor Hadrian to the city. It is the only remaining entrance gate in the walls that surrounded the city of Antalya in ancient times.', 'Walking through a 1,900-year-old Roman arch into Antalya''s old city is one of the most iconic introductions to the city''s deep history.', 30, NULL, 1, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:turkey-antalya-kaleici', 'Kaleici', 'district', 36.884100, 30.705600, 'Antalya', 'Turkey', 'The historic old town of Antalya, a maze of narrow cobblestone streets lined with Ottoman-era wooden houses, boutique hotels, restaurants, and shops, enclosed by ancient Roman and Byzantine walls. It surrounds the old harbor and contains most of the city''s significant historic landmarks.', 'Kaleici is the soul of Antalya — wandering its lanes is the essential experience for any first-time visitor.', 180, NULL, 1, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:turkey-antalya-antalya-museum', 'Antalya Museum', 'museum', 36.887000, 30.683000, 'Antalya', 'Turkey', 'One of Turkey''s largest archaeological museums, housing artifacts spanning prehistoric times through the Byzantine era, including outstanding collections of Roman statues from nearby Perge. It features 13 exhibition halls and an open-air gallery.', 'Considered one of the finest archaeological museums in Turkey, it provides essential context for the ancient ruins scattered across the region.', 150, NULL, 1, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:turkey-antalya-yivli-minare-mosque', 'Yivli Minare Mosque', 'mosque', 36.885500, 30.704500, 'Antalya', 'Turkey', 'A 13th-century Seljuk-era mosque famous for its distinctive fluted brick minaret, which has become a symbol of Antalya. Built by Sultan Alaeddin Keykubad I, it is one of the oldest surviving examples of Seljuk architecture in the region.', 'The fluted minaret is Antalya''s most recognizable skyline icon and a masterpiece of Seljuk craftsmanship.', 30, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:turkey-antalya-antalya-old-harbour', 'Antalya Old Harbour', 'landmark', 36.884000, 30.703500, 'Antalya', 'Turkey', 'A picturesque marina nestled below the cliffs of Kaleici, historically the main port of Antalya from the 2nd century BC until the mid-20th century. Today it is a hub for boat tours, seafood restaurants, and waterfront cafes.', 'The view of the harbor from the cliffs above is one of the most photographed scenes in Antalya.', 90, NULL, 1, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:turkey-antalya-duden-waterfalls', 'Duden Waterfalls', 'waterfall', 36.812500, 30.846000, 'Antalya', 'Turkey', 'A series of waterfalls on the Duden River, with the Lower Duden famously cascading 40 meters directly off a cliff into the Mediterranean Sea. The Upper Duden Falls flow through a lush park with caves you can walk behind.', 'The sight of a waterfall plunging directly into the sea is unique and spectacular, especially when viewed from a boat.', 90, NULL, 0, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:turkey-antalya-konyaalti-beach', 'Konyaalti Beach', 'beach', 36.858000, 30.648000, 'Antalya', 'Turkey', 'A long pebble Blue Flag beach stretching for several kilometers along the western side of Antalya, backed by the dramatic Beydaglari mountains. It features a modern promenade with cafes, restaurants, and parks.', 'Swimming in the Mediterranean with snow-capped Taurus mountains in view is a quintessential Antalya experience.', 180, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:turkey-antalya-hidirlik-tower', 'Hidirlik Tower', 'tower', 36.882500, 30.706000, 'Antalya', 'Turkey', 'A 14-meter-tall cylindrical stone tower built in the 2nd century during the Roman period, located at the southern edge of Kaleici overlooking the sea. It likely served as a lighthouse or fortification.', 'The tower is the city''s premier sunset viewpoint, perched dramatically above the cliffs where Kaleici meets the Mediterranean.', 45, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:turkey-antalya-karaalioglu-park', 'Karaalioglu Park', 'park', 36.881000, 30.708000, 'Antalya', 'Turkey', 'A large, well-maintained public park along the cliffs at the southern edge of Kaleici, filled with palm trees, flowers, and walking paths. It offers panoramic views of the Mediterranean and the Beydaglari mountains.', 'The park''s clifftop terraces deliver some of the best free panoramic views in the city.', 60, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:turkey-antalya-perge-ancient-city', 'Perge Ancient City', 'historic', 36.961400, 30.854200, 'Antalya', 'Turkey', 'An ancient Greek and Roman city located about 15 km east of Antalya, featuring a remarkably preserved stadium, theater, colonnaded street, agora, and Roman baths. It was an important city in Pamphylia and was visited by the Apostle Paul.', 'Perge offers one of the most complete and walkable Roman city ruins in Turkey, with virtually no crowds compared to Ephesus.', 150, NULL, 0, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:turkey-antalya-aspendos-theatre', 'Aspendos Theatre', 'historic', 36.939200, 31.172200, 'Antalya', 'Turkey', 'A Roman theater built in 155 AD under Marcus Aurelius, widely considered the best-preserved ancient theater in the world with seating capacity for 15,000. It still hosts opera and ballet performances each summer.', 'Aspendos is arguably the most intact Roman theater on Earth and standing in its arena is genuinely transporting.', 90, NULL, 0, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:turkey-antalya-tunektepe-teleferik', 'Tunektepe Teleferik', 'viewpoint', 36.826700, 30.589400, 'Antalya', 'Turkey', 'A cable car that ascends 605 meters up Tunek Hill on the western edge of Antalya''s bay, ending at an observation deck with a restaurant. The 10-minute ride offers sweeping views over the Mediterranean coastline.', 'The summit delivers the single best panoramic view of Antalya''s entire bay, mountains, and city skyline.', 90, NULL, 0, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:south-korea-seoul-gyeongbokgung-palace', 'Gyeongbokgung Palace', 'palace', 37.579600, 126.977000, 'Seoul', 'South Korea', 'The largest of Seoul''s Five Grand Palaces, built in 1395 as the main royal palace of the Joseon dynasty. The complex includes throne halls, gardens, and the National Folk Museum, with hourly royal guard-changing ceremonies at the main gate.', 'It''s the symbolic heart of Korean royal history and the most photographed cultural landmark in the country.', 150, NULL, 1, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:south-korea-seoul-n-seoul-tower', 'N Seoul Tower', 'observation_deck', 37.551200, 126.988200, 'Seoul', 'South Korea', 'A 236-meter communication and observation tower perched atop Namsan Mountain, opened to the public in 1980. Reachable by cable car, bus, or hike, it offers 360-degree views of the city skyline.', 'It''s the postcard view of Seoul and the city''s most recognizable skyline landmark.', 120, NULL, 1, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:south-korea-seoul-bukchon-hanok-village', 'Bukchon Hanok Village', 'district', 37.582600, 126.983000, 'Seoul', 'South Korea', 'A preserved residential neighborhood of roughly 900 traditional Korean hanok houses dating back to the Joseon dynasty, nestled between Gyeongbokgung and Changdeokgung palaces. The narrow alleys remain a living neighborhood with workshops, tea houses, and guesthouses.', 'It''s the best place in Seoul to walk through centuries-old Korean architecture in a real urban setting.', 90, NULL, 1, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:south-korea-seoul-myeongdong', 'Myeongdong', 'district', 37.563600, 126.986900, 'Seoul', 'South Korea', 'Seoul''s most famous shopping and street-food district, packed with cosmetics flagships, fashion retailers, and night-market food carts. The area surrounds the historic Myeongdong Cathedral.', 'It''s the quintessential Seoul street-food and K-beauty shopping experience.', 120, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:south-korea-seoul-changdeokgung-palace', 'Changdeokgung Palace', 'palace', 37.579400, 126.991000, 'Seoul', 'South Korea', 'A UNESCO World Heritage palace built in 1405, famed for its Secret Garden (Huwon) that blends seamlessly into the natural topography. It served as the principal royal residence for much of the Joseon dynasty.', 'Its Secret Garden is considered the finest example of Korean traditional landscape design.', 150, NULL, 0, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:south-korea-seoul-gwangjang-market', 'Gwangjang Market', 'market', 37.570300, 127.000800, 'Seoul', 'South Korea', 'One of Korea''s oldest traditional markets, established in 1905, with hundreds of food stalls famed for bindaetteok (mung-bean pancake), mayak gimbap, and live octopus. The market also sells textiles and vintage clothing on its upper floors.', 'It''s the most atmospheric place in Seoul to eat classic Korean street food alongside locals.', 90, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:south-korea-seoul-dongdaemun-design-plaza', 'Dongdaemun Design Plaza', 'landmark', 37.566900, 127.009500, 'Seoul', 'South Korea', 'A futuristic neofuturist landmark designed by Zaha Hadid, opened in 2014, housing design exhibitions, museums, and a 24-hour fashion shopping district around it. Its curving aluminum-paneled facade is illuminated at night.', 'It''s the architectural icon of modern Seoul and the heart of the city''s design and night-shopping scene.', 90, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:south-korea-seoul-cheonggyecheon', 'Cheonggyecheon', 'park', 37.569300, 126.978400, 'Seoul', 'South Korea', 'A 10.9-kilometer recreated stream running through downtown Seoul, restored in 2005 after decades of being covered by an elevated highway. The sunken walkway features public art, bridges, and seasonal light installations.', 'It''s the celebrated example of Seoul''s urban renewal and a peaceful walk through the city center.', 60, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:south-korea-seoul-insadong', 'Insadong', 'district', 37.574400, 126.985100, 'Seoul', 'South Korea', 'A traditional cultural district lined with antique shops, art galleries, calligraphy stores, and traditional tea houses. The main street is car-free on weekends and centered around the Ssamzigil arts complex.', 'It''s the best district in Seoul for traditional Korean crafts, art, and tea culture.', 90, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:south-korea-seoul-jogyesa-temple', 'Jogyesa Temple', 'temple', 37.574400, 126.983100, 'Seoul', 'South Korea', 'The chief temple of the Jogye Order of Korean Buddhism, founded in its current location in 1910. The main hall houses three large gilded Buddha statues, and the courtyard is famed for spectacular lantern displays during Buddha''s Birthday.', 'It''s the most accessible active Buddhist temple in central Seoul.', 45, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:south-korea-seoul-lotte-world-tower-seoul-sky', 'Lotte World Tower Seoul Sky', 'observation_deck', 37.512600, 127.102500, 'Seoul', 'South Korea', 'The observation deck of the 555-meter Lotte World Tower, South Korea''s tallest building, opened in 2017. The deck on floors 117-123 includes a glass-floor skywalk and panoramic views over the Han River.', 'It offers the highest view in Korea and a sweeping perspective of southern Seoul.', 90, NULL, 0, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:south-korea-seoul-war-memorial-of-korea', 'War Memorial of Korea', 'museum', 37.536900, 126.977400, 'Seoul', 'South Korea', 'A large military history museum opened in 1994 covering Korean wars from ancient times to the Korean War, with extensive indoor galleries and an outdoor display of tanks, aircraft, and naval vessels. Admission to the museum is free.', 'It''s the most comprehensive way to understand the Korean War and the divided peninsula''s modern history.', 150, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:saudi-arabia-mecca-masjid-al-haram', 'Masjid al-Haram', 'mosque', 21.422500, 39.826200, 'Mecca', 'Saudi Arabia', 'The Great Mosque of Mecca, the largest mosque in the world, surrounds the Kaaba and is the holiest site in Islam. Access is restricted to Muslims only; non-Muslims are prohibited from entering Mecca''s haram boundary.', 'The center of the Islamic world and the direction every Muslim faces in prayer — the single most spiritually significant site for over a billion people.', 240, NULL, 1, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:saudi-arabia-mecca-kaaba', 'Kaaba', 'religious', 21.422500, 39.826200, 'Mecca', 'Saudi Arabia', 'The cube-shaped sacred structure at the center of Masjid al-Haram, draped in the black kiswah cloth, considered by Muslims to be the House of God. Access is limited to Muslims only.', 'The qibla — the focal point of Islamic prayer worldwide and the goal of the Hajj pilgrimage performed by millions each year.', 60, NULL, 1, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:saudi-arabia-mecca-abraj-al-bait-makkah-royal-clock-tower', 'Abraj Al Bait (Makkah Royal Clock Tower)', 'tower', 21.418900, 39.826300, 'Mecca', 'Saudi Arabia', 'A government-owned megatall complex featuring the world''s largest clock face, towering directly opposite Masjid al-Haram at 601 meters tall. It houses hotels, a shopping mall, and an observation deck.', 'The defining feature of Mecca''s modern skyline and one of the tallest buildings in the world, visible from nearly anywhere in the city.', 120, NULL, 1, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:saudi-arabia-mecca-jabal-al-nour', 'Jabal al-Nour', 'landmark', 21.457700, 39.859700, 'Mecca', 'Saudi Arabia', 'A mountain northeast of Mecca containing the Cave of Hira, where Muslims believe Prophet Muhammad received the first revelations of the Quran. The hike to the summit takes 1-2 hours.', 'One of the most historically significant sites in Islam and a moderately challenging climb rewarded with views over the holy city.', 180, NULL, 1, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:saudi-arabia-mecca-jabal-thawr', 'Jabal Thawr', 'landmark', 21.375600, 39.858900, 'Mecca', 'Saudi Arabia', 'A mountain south of Mecca containing the Cave of Thawr, where Prophet Muhammad and Abu Bakr hid during their migration to Medina. The climb to the cave takes around 1.5 hours.', 'A pivotal site in early Islamic history that pilgrims often visit to retrace the Prophet''s footsteps.', 180, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:saudi-arabia-mecca-jabal-arafat-mount-arafat', 'Jabal Arafat (Mount Arafat)', 'landmark', 21.354800, 39.984300, 'Mecca', 'Saudi Arabia', 'A granite hill east of Mecca, also known as Jabal ar-Rahmah (Mount of Mercy), where Prophet Muhammad delivered his Farewell Sermon. Standing here is the central ritual of Hajj.', 'The climactic site of the Hajj pilgrimage where millions gather annually on the Day of Arafat.', 90, NULL, 1, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:saudi-arabia-mecca-mina', 'Mina', 'district', 21.413300, 39.893300, 'Mecca', 'Saudi Arabia', 'A valley and tent city east of Mecca where Hajj pilgrims stay during the pilgrimage and perform the symbolic stoning of the devil at the Jamarat. Outside Hajj season it is largely empty.', 'Known as the ''City of Tents'' for its 100,000+ air-conditioned tents, it is one of the world''s most unusual urban landscapes during Hajj.', 120, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:saudi-arabia-mecca-muzdalifah', 'Muzdalifah', 'district', 21.383300, 39.933300, 'Mecca', 'Saudi Arabia', 'An open area between Mina and Arafat where Hajj pilgrims spend the night under the stars and collect pebbles for the stoning ritual. It is one of the required stops of the pilgrimage.', 'A required Hajj station where pilgrims experience a night of communal prayer in the open desert.', 60, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:saudi-arabia-mecca-jamarat-bridge', 'Jamarat Bridge', 'landmark', 21.422500, 39.872800, 'Mecca', 'Saudi Arabia', 'A multi-level pedestrian bridge in Mina housing the three Jamarat pillars that pilgrims symbolically stone during Hajj. The structure was rebuilt to handle millions of pilgrims safely.', 'One of the largest pedestrian infrastructure projects in the world, central to the Hajj ritual.', 60, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:saudi-arabia-mecca-makkah-museum', 'Makkah Museum', 'museum', 21.401900, 39.798900, 'Mecca', 'Saudi Arabia', 'Located in the historic Al-Zahir Palace, the museum displays artifacts related to the history of Mecca, the Kaaba, and Islamic heritage. Exhibits include old kiswah cloths and ancient manuscripts.', 'The best place to understand the deep history of Mecca beyond the religious rituals.', 90, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:saudi-arabia-mecca-exhibition-of-the-two-holy-mosques-architecture', 'Exhibition of the Two Holy Mosques Architecture', 'museum', 21.407200, 39.810800, 'Mecca', 'Saudi Arabia', 'A museum showcasing the architectural history of Masjid al-Haram and the Prophet''s Mosque in Medina, with original pieces from past expansions including doors, columns, and a staircase of the Kaaba.', 'Houses the original wooden door of the Kaaba and other irreplaceable artifacts you cannot see anywhere else.', 60, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:saudi-arabia-mecca-clock-tower-museum', 'Clock Tower Museum', 'museum', 21.418900, 39.826300, 'Mecca', 'Saudi Arabia', 'An astronomy and science museum located in the upper floors of the Abraj Al Bait clock tower, featuring exhibits on timekeeping, the solar system, and the mechanics of the giant clock.', 'Combines a science museum experience with one of the highest observation decks in the Islamic world overlooking the Kaaba.', 120, NULL, 0, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:saudi-arabia-mecca-cave-of-hira', 'Cave of Hira', 'historic', 21.457700, 39.859700, 'Mecca', 'Saudi Arabia', 'A small cave near the summit of Jabal al-Nour where, according to Islamic tradition, the angel Gabriel first revealed verses of the Quran to Prophet Muhammad. It requires a steep climb to reach.', 'The literal birthplace of the Quranic revelation and one of the most spiritually charged sites in Islamic history.', 60, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:thailand-phuket-big-buddha-phuket', 'Big Buddha Phuket', 'religious', 7.827500, 98.312200, 'Phuket', 'Thailand', 'A 45-meter-tall white marble Buddha statue seated atop Nakkerd Hill between Chalong and Kata. Completed in 2008 and visible from much of southern Phuket, it remains one of the island''s most important religious landmarks.', 'The panoramic 360-degree views over Phuket combined with the sheer scale of the statue make it the island''s signature spiritual landmark.', 90, NULL, 1, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:thailand-phuket-wat-chalong', 'Wat Chalong', 'temple', 7.846700, 98.337800, 'Phuket', 'Thailand', 'Phuket''s largest and most revered Buddhist temple, featuring a multi-tiered grand pagoda (Phra Mahathat Chedi) said to enshrine a bone fragment of the Buddha. The temple complex honors revered monks Luang Pho Chaem and Luang Pho Chuang.', 'It is the spiritual heart of Phuket and the most ornate Thai temple on the island.', 60, NULL, 1, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:thailand-phuket-patong-beach', 'Patong Beach', 'beach', 7.896500, 98.296500, 'Phuket', 'Thailand', 'A 3-kilometer crescent of sand on Phuket''s west coast that anchors the island''s busiest resort town. The beach is fringed by Bangla Road, Phuket''s main nightlife strip.', 'It is the most famous beach in Phuket and the epicenter of the island''s nightlife and street energy.', 120, NULL, 1, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:thailand-phuket-phuket-old-town', 'Phuket Old Town', 'district', 7.884500, 98.387700, 'Phuket', 'Thailand', 'The historic core of Phuket Town, lined with pastel-colored Sino-Portuguese shophouses built during the 19th-century tin mining boom. The district centers on Thalang, Dibuk, and Soi Romanee streets.', 'It is the only place in Phuket that shows the island''s colonial-era trading heritage, with photogenic architecture you cannot see anywhere else.', 120, NULL, 1, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:thailand-phuket-promthep-cape', 'Promthep Cape', 'viewpoint', 7.762500, 98.305000, 'Phuket', 'Thailand', 'A rocky headland at the southernmost tip of Phuket island, jutting into the Andaman Sea. It is the most popular sunset viewpoint on the island.', 'Watching the sun set over the Andaman from Promthep Cape is a near-mandatory Phuket ritual.', 60, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:thailand-phuket-kata-beach', 'Kata Beach', 'beach', 7.820000, 98.298600, 'Phuket', 'Thailand', 'A 1.5-kilometer arc of soft white sand on the southwest coast, more relaxed than Patong and popular with families and surfers during monsoon season.', 'It offers Phuket''s classic postcard beach scene without Patong''s intensity.', 120, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:thailand-phuket-karon-viewpoint', 'Karon Viewpoint', 'viewpoint', 7.782500, 98.306000, 'Phuket', 'Thailand', 'A roadside lookout on the southwestern coastal road, also known as Kata Viewpoint or the Three Beaches Viewpoint. It overlooks Kata Noi, Kata, and Karon beaches in a single sweeping panorama.', 'It is the single best photo spot capturing Phuket''s iconic curved bays in one frame.', 30, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:thailand-phuket-bangla-road', 'Bangla Road', 'district', 7.893900, 98.297500, 'Phuket', 'Thailand', 'A 400-meter pedestrian street in Patong that closes to traffic each evening and fills with bars, clubs, and street performers. It is Phuket''s most concentrated nightlife zone.', 'Walking Bangla Road at night is the defining nightlife experience of Phuket.', 90, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:thailand-phuket-phi-phi-islands', 'Phi Phi Islands', 'nature_reserve', 7.740700, 98.778400, 'Phuket', 'Thailand', 'An archipelago of six limestone karst islands in the Andaman Sea, reached by boat from Phuket. The group includes Phi Phi Don, Phi Phi Leh, and the famous Maya Bay.', 'The towering cliffs, turquoise water, and Maya Bay make this the most iconic day trip from Phuket.', 480, NULL, 1, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:thailand-phuket-phang-nga-bay', 'Phang Nga Bay', 'nature_reserve', 8.283300, 98.583300, 'Phuket', 'Thailand', 'A protected marine bay north of Phuket dotted with sheer limestone karsts rising vertically from the sea, including the famous James Bond Island (Khao Phing Kan). It is typically visited by longtail or speedboat day trip.', 'The dramatic karst seascape is one of Southeast Asia''s most photographed natural wonders.', 420, NULL, 0, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:thailand-phuket-phuket-weekend-night-market', 'Phuket Weekend Night Market', 'market', 7.874200, 98.385800, 'Phuket', 'Thailand', 'Also known as Naka Market or Talad Tairod, this large weekend market near Phuket Town runs Saturday and Sunday evenings. It sells street food, clothing, and household goods to a mostly local crowd.', 'It is the most authentic local market experience on the island and a cheap way to eat through Thai street food classics.', 90, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:thailand-phuket-wat-phra-thong', 'Wat Phra Thong', 'temple', 8.008900, 98.337500, 'Phuket', 'Thailand', 'A historic temple in Thalang district housing a half-buried golden Buddha image that, according to local legend, cannot be fully excavated. It is one of the oldest temples on Phuket.', 'Its centuries-old half-buried Buddha legend makes it Phuket''s most unusual sacred site.', 45, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:italy-rome-colosseum', 'Colosseum', 'historic', 41.890200, 12.492200, 'Rome', 'Italy', 'A massive Roman amphitheater completed in 80 AD that once hosted gladiatorial contests and public spectacles for up to 50,000 spectators. It is the largest ancient amphitheater ever built and a UNESCO World Heritage Site.', 'It is the single most recognizable symbol of ancient Rome and arguably the most iconic building of the entire Roman Empire.', 120, NULL, 1, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:italy-rome-roman-forum', 'Roman Forum', 'historic', 41.892500, 12.485300, 'Rome', 'Italy', 'A sprawling archaeological site of ruined temples, basilicas, and arches that served as the political, religious, and commercial heart of ancient Rome. It sits in a valley between the Palatine and Capitoline hills.', 'Walking through the Forum is walking the same paved streets where Julius Caesar, Cicero, and Augustus shaped Western civilization.', 120, NULL, 1, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:italy-rome-vatican-museums', 'Vatican Museums', 'museum', 41.906500, 12.453600, 'Rome', 'Italy', 'One of the largest and most important museum complexes in the world, housing the papal art collection accumulated over centuries. The visit culminates in the Sistine Chapel, painted by Michelangelo.', 'Home to Michelangelo''s Sistine Chapel ceiling and Raphael''s Rooms, it holds some of the most important artworks in human history.', 240, NULL, 1, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:italy-rome-st-peter-s-basilica', 'St. Peter''s Basilica', 'cathedral', 41.902200, 12.453900, 'Rome', 'Italy', 'The largest church in the world by interior size and the spiritual center of the Catholic Church, built over the tomb of Saint Peter. Its dome was designed by Michelangelo and the interior holds Bernini''s baldachin and Michelangelo''s Pieta.', 'Free to enter and unmatched in scale, it is the most important Renaissance and Baroque church on Earth.', 90, NULL, 1, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:italy-rome-pantheon', 'Pantheon', 'historic', 41.898600, 12.476900, 'Rome', 'Italy', 'A former Roman temple completed around 126 AD under Emperor Hadrian, now a Catholic church. It features the world''s largest unreinforced concrete dome with a 9-meter open oculus at its center.', 'The best-preserved building from ancient Rome, with an engineering feat that went unmatched for over 1,300 years.', 30, NULL, 0, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:italy-rome-trevi-fountain', 'Trevi Fountain', 'monument', 41.900900, 12.483300, 'Rome', 'Italy', 'A monumental Baroque fountain completed in 1762, depicting Oceanus flanked by Tritons and seahorses against a sculpted backdrop. It stands roughly 26 meters tall and 49 meters wide.', 'Tossing a coin into the world''s most famous fountain is a Rome tradition that supposedly guarantees your return.', 30, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:italy-rome-piazza-navona', 'Piazza Navona', 'square', 41.899200, 12.473100, 'Rome', 'Italy', 'An elongated Baroque public square built on the site of the ancient Stadium of Domitian, lined with cafes and palaces. It features three fountains, including Bernini''s celebrated Fountain of the Four Rivers.', 'The most beautiful Baroque square in Rome and a free, lively snapshot of Italian street life.', 30, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:italy-rome-spanish-steps', 'Spanish Steps', 'landmark', 41.906000, 12.482800, 'Rome', 'Italy', 'A monumental staircase of 135 steps built in the 1720s, linking the Piazza di Spagna at the base with the Trinita dei Monti church at the top. The Barcaccia fountain by Bernini sits at the foot of the steps.', 'An elegant Roman gathering spot since the 18th century and one of the most photographed staircases in the world.', 30, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:italy-rome-castel-sant-angelo', 'Castel Sant''Angelo', 'fortress', 41.903100, 12.466300, 'Rome', 'Italy', 'A cylindrical fortress on the Tiber River originally commissioned by Emperor Hadrian as a mausoleum around 139 AD, later used as a papal fortress and prison. It is connected to the Vatican by a fortified corridor.', 'Climb to the top for one of the best panoramic views of Rome and St. Peter''s dome across the river.', 90, NULL, 0, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:italy-rome-villa-borghese-gardens', 'Villa Borghese Gardens', 'park', 41.913900, 12.492000, 'Rome', 'Italy', 'A large landscaped public park covering about 80 hectares, originally laid out in the 17th century for the Borghese family. It contains the Galleria Borghese museum, fountains, lakes, and viewpoints.', 'Rome''s green lung offers a free escape from the crowds plus the Pincio terrace overlooking the city.', 90, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:italy-rome-trastevere', 'Trastevere', 'district', 41.889600, 12.469500, 'Rome', 'Italy', 'A medieval neighborhood on the west bank of the Tiber known for narrow cobblestone alleys, ivy-covered facades, and the ancient Basilica of Santa Maria in Trastevere. It is one of the oldest continuously inhabited parts of Rome.', 'The most atmospheric neighborhood in Rome for evening wandering, trattorias, and authentic local character.', 120, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:italy-rome-piazza-del-campidoglio', 'Piazza del Campidoglio', 'square', 41.893200, 12.482800, 'Rome', 'Italy', 'A monumental hilltop square designed by Michelangelo atop the Capitoline Hill, framed by three palaces that house the Capitoline Museums. A replica of the equestrian statue of Marcus Aurelius stands at the center.', 'Michelangelo''s only urban square design and the gateway to the world''s oldest public museums.', 45, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:spain-barcelona-sagrada-familia', 'Sagrada Familia', 'cathedral', 41.403600, 2.174400, 'Barcelona', 'Spain', 'Antoni Gaudi''s monumental unfinished basilica, under construction since 1882 and a UNESCO World Heritage Site. Its soaring towers, organic forms, and stained-glass-lit interior are unlike any other church on earth.', 'It is the singular icon of Barcelona and arguably the most extraordinary work of architecture built in the past 150 years.', 120, NULL, 1, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:spain-barcelona-park-guell', 'Park Guell', 'park', 41.414500, 2.152700, 'Barcelona', 'Spain', 'A whimsical hillside public park designed by Antoni Gaudi between 1900 and 1914, featuring mosaic-tiled terraces, serpentine benches, and fairytale gatehouses. The Monumental Zone requires a ticket; the surrounding park is free.', 'Its trencadis mosaics and panoramic terrace over Barcelona are among the most photographed views in Spain.', 120, NULL, 1, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:spain-barcelona-casa-batllo', 'Casa Batllo', 'landmark', 41.391700, 2.164900, 'Barcelona', 'Spain', 'A Gaudi-designed modernist townhouse on Passeig de Gracia, completed in 1906, with a skeletal facade, scaled roof, and dreamlike interiors. It is one of the masterpieces of Catalan Modernisme.', 'Its bone-like balconies and dragon-back roof make it the most visually striking building on Barcelona''s grandest avenue.', 90, NULL, 0, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:spain-barcelona-la-pedrera-casa-mila', 'La Pedrera - Casa Mila', 'landmark', 41.395400, 2.162000, 'Barcelona', 'Spain', 'Gaudi''s final civil work, a wave-fronted stone apartment building completed in 1912 and now a UNESCO site. Visitors tour the attic, apartment, and surreal chimney-studded rooftop.', 'The undulating limestone facade and warrior-like rooftop chimneys are pure Gaudi at his most sculptural.', 90, NULL, 0, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:spain-barcelona-gothic-quarter', 'Gothic Quarter', 'district', 41.383300, 2.176700, 'Barcelona', 'Spain', 'The medieval heart of Barcelona, a dense maze of narrow stone lanes, hidden squares, and Roman-era ruins between Las Ramblas and Via Laietana. Home to the Barcelona Cathedral and Placa Reial.', 'Wandering its lamplit alleys at dusk is the city''s most atmospheric free experience.', 120, NULL, 1, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:spain-barcelona-la-rambla', 'La Rambla', 'district', 41.380900, 2.172900, 'Barcelona', 'Spain', 'Barcelona''s famous 1.2-kilometer tree-lined pedestrian boulevard running from Placa de Catalunya down to the Columbus Monument at the port. Lined with kiosks, street performers, and historic cafes.', 'It is the city''s central promenade and a rite of passage for any first-time visitor.', 60, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:spain-barcelona-mercat-de-la-boqueria', 'Mercat de la Boqueria', 'market', 41.381900, 2.171800, 'Barcelona', 'Spain', 'An iconic public food market on La Rambla with origins dating to 1217 and its current Modernista hall completed in 1914. Stalls overflow with Iberian ham, seafood, fruit, and tapas counters.', 'It is the most famous food market in Spain and a sensory snapshot of Catalan cuisine.', 60, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:spain-barcelona-camp-nou', 'Camp Nou', 'landmark', 41.380900, 2.122800, 'Barcelona', 'Spain', 'The legendary home stadium of FC Barcelona, opened in 1957 and Europe''s largest football stadium by capacity. Currently undergoing a major renovation, with the on-site museum experience continuing in modified form.', 'It is a pilgrimage site for football fans and a symbol of Catalan identity through FC Barcelona.', 120, NULL, 0, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:spain-barcelona-montjuic-castle', 'Montjuic Castle', 'fortress', 41.363700, 2.165900, 'Barcelona', 'Spain', 'A 17th-century military fortress perched atop Montjuic hill overlooking Barcelona''s port. Reached by cable car or a winding hillside walk, with sweeping views over the city and Mediterranean.', 'It offers the single best panoramic view of Barcelona and the harbor.', 90, NULL, 0, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:spain-barcelona-magic-fountain-of-montjuic', 'Magic Fountain of Montjuic', 'landmark', 41.371100, 2.151700, 'Barcelona', 'Spain', 'A monumental fountain built for the 1929 International Exposition, sitting below Palau Nacional at the foot of Montjuic. Famous for evening shows synchronizing water, light, and music.', 'Its free nightly choreographed water show is a beloved Barcelona ritual.', 45, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:spain-barcelona-barceloneta-beach', 'Barceloneta Beach', 'beach', 41.378400, 2.192500, 'Barcelona', 'Spain', 'Barcelona''s most popular urban beach, fronting the old fishermen''s quarter of Barceloneta and reshaped for the 1992 Olympics. A long strip of golden sand backed by chiringuitos and a palm-lined promenade.', 'Few major cities offer a real Mediterranean beach a short walk from the medieval center.', 90, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:spain-barcelona-picasso-museum-barcelona', 'Picasso Museum Barcelona', 'museum', 41.385100, 2.181000, 'Barcelona', 'Spain', 'A museum housed in five adjoining medieval palaces in the Born district, holding one of the most extensive collections of Pablo Picasso''s early works. Founded in 1963 with the artist''s personal involvement.', 'It traces Picasso''s formative years in Barcelona better than any other museum in the world.', 120, NULL, 0, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:netherlands-amsterdam-rijksmuseum', 'Rijksmuseum', 'museum', 52.360000, 4.885200, 'Amsterdam', 'Netherlands', 'The Netherlands'' national museum, housing 8,000 objects of art and history including masterpieces by Rembrandt, Vermeer, and Frans Hals. The building, designed by Pierre Cuypers, opened at its current location in 1885.', 'Home to Rembrandt''s ''The Night Watch'' and Vermeer''s ''The Milkmaid'', it is the definitive showcase of the Dutch Golden Age.', 180, NULL, 1, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:netherlands-amsterdam-van-gogh-museum', 'Van Gogh Museum', 'museum', 52.358400, 4.881100, 'Amsterdam', 'Netherlands', 'A museum dedicated to the works of Vincent van Gogh and his contemporaries, holding the largest collection of his paintings and drawings in the world. It opened in 1973 on Museumplein.', 'Nowhere else can you trace Van Gogh''s entire artistic journey through 200+ paintings including ''Sunflowers'' and ''The Bedroom''.', 150, NULL, 1, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:netherlands-amsterdam-anne-frank-house', 'Anne Frank House', 'museum', 52.375200, 4.884000, 'Amsterdam', 'Netherlands', 'The canal-side house where Anne Frank and her family hid from Nazi persecution during WWII, preserved as a biographical museum. The Secret Annex behind the bookcase is open to visitors.', 'Walking through the actual hiding place where Anne wrote her diary is one of the most moving historical experiences in Europe.', 90, NULL, 1, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:netherlands-amsterdam-vondelpark', 'Vondelpark', 'park', 52.358000, 4.868600, 'Amsterdam', 'Netherlands', 'A 47-hectare public urban park opened in 1865, named after the 17th-century poet Joost van den Vondel. It features ponds, a rose garden, and an open-air theatre.', 'Amsterdam''s most beloved green space where locals jog, picnic, and gather, offering the best free taste of everyday Dutch city life.', 90, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:netherlands-amsterdam-dam-square', 'Dam Square', 'square', 52.373100, 4.892600, 'Amsterdam', 'Netherlands', 'The historic central square of Amsterdam, named after the original 13th-century dam built on the Amstel river. It is flanked by the Royal Palace, Nieuwe Kerk, and the National Monument.', 'The symbolic heart of the city since medieval times, where every visitor inevitably passes through at least once.', 30, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:netherlands-amsterdam-royal-palace-amsterdam', 'Royal Palace Amsterdam', 'palace', 52.373100, 4.891300, 'Amsterdam', 'Netherlands', 'A 17th-century palace on Dam Square, originally built as the city hall during the Dutch Golden Age and now one of three palaces used by the Dutch royal family. It is renowned for its grand Citizens'' Hall.', 'A monumental symbol of Amsterdam''s Golden Age wealth, with sumptuous marble interiors that rival any European palace.', 75, NULL, 0, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:netherlands-amsterdam-jordaan', 'Jordaan', 'district', 52.374200, 4.883000, 'Amsterdam', 'Netherlands', 'A historic neighborhood built in the 17th century, originally for working-class residents and now one of Amsterdam''s most charming and desirable districts. It is full of narrow streets, hidden courtyards (hofjes), galleries, and brown cafes.', 'The most atmospheric quarter of Amsterdam, perfect for wandering canals away from the tourist crowds.', 120, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:netherlands-amsterdam-bloemenmarkt', 'Bloemenmarkt', 'market', 52.366700, 4.891700, 'Amsterdam', 'Netherlands', 'The world''s only floating flower market, established in 1862, with stalls built on houseboats along the Singel canal. It sells tulip bulbs, seeds, and fresh-cut flowers.', 'A quintessentially Dutch experience capturing the country''s centuries-old love affair with tulips.', 45, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:netherlands-amsterdam-westerkerk', 'Westerkerk', 'cathedral', 52.374700, 4.883600, 'Amsterdam', 'Netherlands', 'A Dutch Reformed church completed in 1631 with the tallest church tower in Amsterdam at 87 meters, known as the Westertoren. Rembrandt is buried somewhere within the church.', 'Its iconic crowned tower defines the Amsterdam skyline and chimes throughout the Jordaan, immortalized in Anne Frank''s diary.', 30, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:netherlands-amsterdam-begijnhof', 'Begijnhof', 'historic', 52.369700, 4.889800, 'Amsterdam', 'Netherlands', 'A medieval inner courtyard founded in the 14th century, originally housing the Beguines, a Catholic sisterhood. It contains one of Amsterdam''s oldest wooden houses (Het Houten Huys, c.1420) and two historic chapels.', 'A serene, hidden enclave just steps from the busy center, offering a rare glimpse of medieval Amsterdam.', 30, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:netherlands-amsterdam-albert-cuyp-market', 'Albert Cuyp Market', 'market', 52.355600, 4.893900, 'Amsterdam', 'Netherlands', 'The largest and best-known street market in the Netherlands, operating in De Pijp neighborhood since 1905. Around 260 stalls sell everything from stroopwafels and herring to clothing and flowers.', 'The most authentic place to sample Dutch street food like fresh stroopwafels and raw herring alongside locals.', 60, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:italy-milan-duomo-di-milano', 'Duomo di Milano', 'cathedral', 45.464200, 9.191900, 'Milan', 'Italy', 'A massive Gothic cathedral that took nearly six centuries to complete, featuring 135 spires and over 3,400 statues. It is the largest church in Italy and one of the largest in the world.', 'It is the symbol of Milan and one of the most breathtaking Gothic structures on Earth, with a rooftop terrace that lets you walk among the spires.', 120, NULL, 1, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:italy-milan-galleria-vittorio-emanuele-ii', 'Galleria Vittorio Emanuele II', 'landmark', 45.465900, 9.189900, 'Milan', 'Italy', 'An ornate 19th-century glass-vaulted shopping arcade connecting Piazza del Duomo to Piazza della Scala. It is one of the world''s oldest active shopping galleries.', 'Its iron-and-glass dome, mosaic floors, and luxury boutiques make it the most beautiful shopping arcade in the world and a free architectural marvel to walk through.', 45, NULL, 1, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:italy-milan-santa-maria-delle-grazie', 'Santa Maria delle Grazie', 'religious', 45.465900, 9.170900, 'Milan', 'Italy', 'A 15th-century Dominican convent and UNESCO World Heritage Site that houses Leonardo da Vinci''s mural The Last Supper. Tickets to view the fresco must be reserved weeks in advance.', 'It holds the single most famous painting in Milan, Leonardo''s Last Supper, which no art lover should miss.', 60, NULL, 1, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:italy-milan-teatro-alla-scala', 'Teatro alla Scala', 'landmark', 45.467400, 9.189500, 'Milan', 'Italy', 'Italy''s most prestigious opera house, opened in 1778 and home to legendary performances by Verdi, Puccini, and Maria Callas. The attached museum displays costumes, instruments, and historical memorabilia.', 'It is the most storied opera stage in the world and the spiritual home of Italian opera.', 90, NULL, 1, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:italy-milan-parco-sempione', 'Parco Sempione', 'park', 45.472500, 9.177200, 'Milan', 'Italy', 'A large public park behind Sforza Castle, laid out in the English landscape style in the late 19th century. It contains the Arch of Peace, a pond, and the Triennale design museum.', 'It is Milan''s green heart, a peaceful escape from the urban density with iconic monuments framing every view.', 60, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:italy-milan-pinacoteca-di-brera', 'Pinacoteca di Brera', 'art_gallery', 45.472000, 9.188000, 'Milan', 'Italy', 'One of Italy''s most important art galleries, housed in a 17th-century palace and featuring masterpieces by Raphael, Caravaggio, Mantegna, and Bellini. It anchors the bohemian Brera district.', 'It holds one of the finest collections of Italian Renaissance painting outside of Florence and Rome.', 150, NULL, 0, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:italy-milan-navigli-district', 'Navigli District', 'district', 45.451400, 9.173600, 'Milan', 'Italy', 'A historic canal neighborhood originally designed in part by Leonardo da Vinci, now lined with bars, restaurants, and antique shops. The Naviglio Grande and Naviglio Pavese converge at the Darsena basin.', 'It is Milan''s most atmospheric nightlife area, perfect for aperitivo along the water at sunset.', 120, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:italy-milan-basilica-di-sant-ambrogio', 'Basilica di Sant''Ambrogio', 'religious', 45.462400, 9.175800, 'Milan', 'Italy', 'One of the oldest churches in Milan, founded in 379 AD by Saint Ambrose, the city''s patron saint. It is a masterpiece of Romanesque architecture with twin bell towers and an atrium courtyard.', 'It is Milan''s most historically significant church after the Duomo and a foundational example of Lombard Romanesque architecture.', 60, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:italy-milan-quadrilatero-della-moda', 'Quadrilatero della Moda', 'district', 45.468400, 9.195500, 'Milan', 'Italy', 'Milan''s fashion quadrilateral bounded by Via Montenapoleone, Via della Spiga, Via Manzoni, and Corso Venezia. It is home to the flagship boutiques of Prada, Gucci, Armani, Versace, and Dolce & Gabbana.', 'It is the global capital of luxury fashion and an essential window-shopping pilgrimage for any visitor.', 90, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:italy-milan-cimitero-monumentale-di-milano', 'Cimitero Monumentale di Milano', 'historic', 45.485600, 9.179100, 'Milan', 'Italy', 'A vast 19th-century cemetery designed as an open-air museum, filled with elaborate sculptures, mausoleums, and Art Nouveau tombs. Many of Italy''s most important figures are buried here.', 'It is one of Europe''s most artistically extravagant cemeteries and a free outdoor sculpture gallery.', 90, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:italy-milan-bosco-verticale', 'Bosco Verticale', 'landmark', 45.485600, 9.190500, 'Milan', 'Italy', 'A pair of residential towers in the Porta Nuova district covered with over 20,000 trees and plants. Completed in 2014, it is a landmark of sustainable architecture.', 'It represents the modern face of Milan and is one of the most photographed contemporary buildings in Europe.', 30, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:japan-osaka-osaka-castle', 'Osaka Castle', 'fortress', 34.687300, 135.526200, 'Osaka', 'Japan', 'A reconstructed 16th-century castle originally built by Toyotomi Hideyoshi, now housing a museum about its history. The grounds include a large public park, moats, and stone walls.', 'Osaka''s defining historical landmark and the symbol most associated with the city''s samurai-era past.', 120, NULL, 1, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:japan-osaka-dotonbori', 'Dotonbori', 'district', 34.668700, 135.501200, 'Osaka', 'Japan', 'A vibrant entertainment and food district running alongside the Dotonbori canal in Namba, famous for massive neon signs including the iconic Glico Running Man. Lined with restaurants, street food stalls, theaters, and shops.', 'The single most photographed street in Osaka and the heart of the city''s food and nightlife culture.', 120, NULL, 1, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:japan-osaka-universal-studios-japan', 'Universal Studios Japan', 'theme_park', 34.665400, 135.432300, 'Osaka', 'Japan', 'A major movie-themed amusement park featuring areas like The Wizarding World of Harry Potter, Super Nintendo World, Minion Park, and Jurassic Park. Operates rides, shows, and seasonal events.', 'One of the most popular theme parks in Asia and home to the world''s first Super Nintendo World.', 480, NULL, 1, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:japan-osaka-shitennoji-temple', 'Shitennoji Temple', 'temple', 34.654300, 135.516500, 'Osaka', 'Japan', 'Founded in 593 AD by Prince Shotoku, this is one of Japan''s oldest officially administered Buddhist temples. The complex includes a five-story pagoda, main hall, and a large outer precinct.', 'The oldest Buddhist temple in Japan and a foundational site of Japanese Buddhism.', 60, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:japan-osaka-sumiyoshi-taisha', 'Sumiyoshi Taisha', 'shrine', 34.612500, 135.493100, 'Osaka', 'Japan', 'One of Japan''s oldest Shinto shrines, founded in the 3rd century and known for its distinctive Sumiyoshi-zukuri architectural style that predates Chinese Buddhist influence. Famous for its arched Sorihashi bridge.', 'An exceptionally rare example of pure native Japanese shrine architecture and one of the country''s most ancient sacred sites.', 60, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:japan-osaka-kuromon-ichiba-market', 'Kuromon Ichiba Market', 'market', 34.666000, 135.506600, 'Osaka', 'Japan', 'A 600-meter covered market street with around 150 shops selling fresh seafood, produce, wagyu beef, and street food. Operating for roughly 200 years and known as ''Osaka''s Kitchen.''', 'The city''s most famous food market and a prime spot to taste Osaka''s culinary specialties.', 90, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:japan-osaka-umeda-sky-building', 'Umeda Sky Building', 'observation_deck', 34.705300, 135.490400, 'Osaka', 'Japan', 'A 173-meter twin-tower skyscraper connected at the top by the Floating Garden Observatory, an open-air rooftop deck. Designed by architect Hiroshi Hara and completed in 1993.', 'Offers Osaka''s most distinctive 360-degree city panorama from a uniquely designed open-air rooftop.', 75, NULL, 0, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:japan-osaka-tsutenkaku-tower', 'Tsutenkaku Tower', 'tower', 34.652500, 135.506300, 'Osaka', 'Japan', 'A 103-meter observation tower in the retro Shinsekai district, originally built in 1912 and rebuilt in 1956. The surrounding neighborhood retains a nostalgic Showa-era atmosphere.', 'An iconic symbol of old downtown Osaka and the centerpiece of the city''s most retro neighborhood.', 60, NULL, 0, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:japan-osaka-osaka-aquarium-kaiyukan', 'Osaka Aquarium Kaiyukan', 'aquarium', 34.654500, 135.429000, 'Osaka', 'Japan', 'One of the largest aquariums in the world, centered on a massive Pacific Ocean tank that houses whale sharks. Visitors descend through habitats representing the Pacific Rim.', 'Home to whale sharks and one of the few aquariums in the world built around a single giant central tank.', 150, NULL, 0, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:japan-osaka-shinsekai', 'Shinsekai', 'district', 34.651900, 135.506100, 'Osaka', 'Japan', 'A retro downtown neighborhood developed in 1912 with northern sections modeled on Paris and southern sections on Coney Island. Famous for kushikatsu restaurants and old-school Showa atmosphere.', 'Feels like stepping into mid-20th-century Osaka and is the city''s best place to try its signature kushikatsu skewers.', 90, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:japan-osaka-hozenji-temple', 'Hozenji Temple', 'temple', 34.668500, 135.501800, 'Osaka', 'Japan', 'A small Buddhist temple tucked down a stone-paved alleyway near Dotonbori, founded in 1637 and home to a moss-covered statue of Fudo Myoo. Visitors splash water on the statue as a prayer.', 'A serene, atmospheric pocket of old Osaka hidden steps from the city''s busiest entertainment district.', 20, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:japan-osaka-nakanoshima-park', 'Nakanoshima Park', 'park', 34.692500, 135.506700, 'Osaka', 'Japan', 'Osaka''s oldest public park, opened in 1891 on an island between the Dojima and Tosabori rivers in the city center. Features a rose garden, riverside promenades, and views of historic buildings like the Osaka Central Public Hall.', 'A peaceful green spine through downtown Osaka with the city''s most beautiful historic civic architecture.', 60, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:austria-vienna-schonbrunn-palace', 'Schonbrunn Palace', 'palace', 48.184500, 16.312200, 'Vienna', 'Austria', 'A 1,441-room Baroque summer residence of the Habsburg monarchs, surrounded by formal gardens, a maze, and the world''s oldest zoo. It is a UNESCO World Heritage Site.', 'It is the definitive symbol of Habsburg imperial grandeur and one of Europe''s most important Baroque palace complexes.', 180, NULL, 1, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:austria-vienna-st-stephen-s-cathedral', 'St. Stephen''s Cathedral', 'cathedral', 48.208500, 16.373100, 'Vienna', 'Austria', 'The Gothic mother church of the Roman Catholic Archdiocese of Vienna, famous for its multicolored tile roof and 136-meter south tower. It has stood at the city''s heart since the 12th century.', 'It is Vienna''s most recognizable landmark and the spiritual and geographic center of the old city.', 60, NULL, 1, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:austria-vienna-hofburg', 'Hofburg', 'palace', 48.206500, 16.365600, 'Vienna', 'Austria', 'The former principal imperial palace of the Habsburg dynasty, now housing the Austrian president''s office, the Sisi Museum, Imperial Apartments, and the Spanish Riding School.', 'It was the seat of one of Europe''s most powerful royal families for over 600 years and remains the political heart of Austria.', 150, NULL, 1, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:austria-vienna-belvedere-palace', 'Belvedere Palace', 'palace', 48.191600, 16.380500, 'Vienna', 'Austria', 'A Baroque palace complex built for Prince Eugene of Savoy, now an art museum housing the world''s largest collection of Gustav Klimt paintings, including ''The Kiss''.', 'It pairs spectacular Baroque architecture and gardens with the most famous painting in Austrian art history.', 150, NULL, 1, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:austria-vienna-vienna-state-opera', 'Vienna State Opera', 'landmark', 48.202700, 16.369100, 'Vienna', 'Austria', 'A Renaissance Revival opera house opened in 1869, considered one of the world''s leading opera venues with a program of around 350 performances per season.', 'Vienna is the global capital of classical music and this is its most prestigious stage.', 90, NULL, 0, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:austria-vienna-prater', 'Prater', 'park', 48.216700, 16.395800, 'Vienna', 'Austria', 'A large public park containing the historic Wurstelprater amusement area, home to the iconic Wiener Riesenrad Ferris wheel built in 1897.', 'The giant Ferris wheel is a Vienna icon featured in ''The Third Man'' and offers a classic skyline view.', 120, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:austria-vienna-naschmarkt', 'Naschmarkt', 'market', 48.198600, 16.363600, 'Vienna', 'Austria', 'Vienna''s largest and most popular open-air market, operating since the 16th century with around 120 stalls selling food, spices, and international cuisine.', 'It is the best place to eat your way through Viennese and international food culture in one walk.', 90, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:austria-vienna-kunsthistorisches-museum-vienna', 'Kunsthistorisches Museum Vienna', 'museum', 48.203800, 16.361400, 'Vienna', 'Austria', 'The Museum of Art History, opened in 1891 in a grand domed building on the Ringstrasse, holding the Habsburg imperial art collection including works by Bruegel, Vermeer, and Caravaggio.', 'It houses one of the most important Old Master painting collections in the world.', 180, NULL, 0, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:austria-vienna-albertina', 'Albertina', 'museum', 48.204900, 16.368300, 'Vienna', 'Austria', 'A museum in the former Habsburg residential palace holding one of the largest and most important print rooms in the world, plus major collections of Monet, Picasso, and Klimt.', 'It combines imperial state rooms with a world-class collection spanning Durer to modern masters.', 120, NULL, 0, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:austria-vienna-karlskirche', 'Karlskirche', 'religious', 48.198300, 16.371900, 'Vienna', 'Austria', 'A Baroque church completed in 1737, dedicated to Saint Charles Borromeo, distinguished by its massive green dome flanked by two columns inspired by Trajan''s Column in Rome.', 'It is the most outstanding Baroque church north of the Alps and an architectural icon of Vienna.', 60, NULL, 0, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:austria-vienna-hundertwasserhaus', 'Hundertwasserhaus', 'landmark', 48.207600, 16.394100, 'Vienna', 'Austria', 'An expressionist apartment building completed in 1985 designed by artist Friedensreich Hundertwasser, with uneven floors, an undulating facade, and trees growing from the rooms.', 'It is Vienna''s most photographed piece of modern architecture and a striking contrast to the city''s imperial style.', 30, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:austria-vienna-stadtpark', 'Stadtpark', 'park', 48.204900, 16.379700, 'Vienna', 'Austria', 'Vienna''s first public park, opened in 1862 along the Ringstrasse, famous for its gilded statue of composer Johann Strauss II playing the violin.', 'The Johann Strauss monument is the most photographed statue in Vienna and a free emblem of the city''s musical heritage.', 45, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:czech-republic-prague-charles-bridge', 'Charles Bridge', 'landmark', 50.086500, 14.411400, 'Prague', 'Czech Republic', 'A 14th-century stone arch bridge across the Vltava River, lined with 30 Baroque statues of saints. Commissioned by King Charles IV in 1357, it connects Old Town with Mala Strana.', 'It is Prague''s most iconic image — a medieval pedestrian bridge framed by Gothic towers and the castle skyline.', 45, NULL, 1, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:czech-republic-prague-prague-castle', 'Prague Castle', 'fortress', 50.091100, 14.401400, 'Prague', 'Czech Republic', 'The largest ancient castle complex in the world, founded in the 9th century and the historic seat of Bohemian kings, Holy Roman emperors, and now the Czech president. The complex includes palaces, gardens, and St. Vitus Cathedral.', 'It dominates the Prague skyline and contains over a thousand years of Czech royal and political history in one walled hilltop city.', 180, NULL, 1, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:czech-republic-prague-old-town-square', 'Old Town Square', 'square', 50.087500, 14.421300, 'Prague', 'Czech Republic', 'The historic central square of Prague''s Old Town, surrounded by Gothic, Baroque, and Rococo buildings including the Church of Our Lady before Tyn and the Old Town Hall. It has been the city''s main marketplace since the 12th century.', 'It is the storybook heart of Prague where the Astronomical Clock chimes and centuries of architecture meet in one open space.', 60, NULL, 1, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:czech-republic-prague-prague-astronomical-clock', 'Prague Astronomical Clock', 'historic', 50.087000, 14.420800, 'Prague', 'Czech Republic', 'A medieval astronomical clock mounted on the Old Town Hall, installed in 1410, making it the third-oldest astronomical clock in the world and the oldest still operating. Every hour, the figures of the Twelve Apostles parade in its windows.', 'Watching the hourly Walk of the Apostles on a 600-year-old working clock is a quintessential Prague ritual.', 30, NULL, 1, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:czech-republic-prague-st-vitus-cathedral', 'St. Vitus Cathedral', 'cathedral', 50.090400, 14.400200, 'Prague', 'Czech Republic', 'A Gothic Roman Catholic cathedral within Prague Castle, begun in 1344 and completed in 1929. It contains the tombs of Bohemian kings and Holy Roman Emperors and the relics of St. Wenceslas.', 'Its soaring Gothic spires define the castle skyline, and its stained glass — including a window by Alphonse Mucha — is among Europe''s finest.', 60, NULL, 0, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:czech-republic-prague-wenceslas-square', 'Wenceslas Square', 'square', 50.081400, 14.428200, 'Prague', 'Czech Republic', 'A long boulevard-style square in the New Town, originally a medieval horse market, dominated by the National Museum and a statue of St. Wenceslas. It has been the site of major Czech historical events including the 1989 Velvet Revolution.', 'It is modern Prague''s civic stage — where the country''s 20th-century history unfolded in public.', 45, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:czech-republic-prague-petrin-lookout-tower', 'Petrin Lookout Tower', 'observation_deck', 50.083600, 14.395300, 'Prague', 'Czech Republic', 'A 63.5-meter steel lattice tower atop Petrin Hill, built in 1891 and modeled loosely on the Eiffel Tower. It offers 360-degree views over Prague and the Vltava valley.', 'It delivers the best panoramic view of Prague''s spires and red rooftops, reached by a hillside funicular.', 75, NULL, 0, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:czech-republic-prague-jewish-quarter-josefov', 'Jewish Quarter Josefov', 'district', 50.090400, 14.419600, 'Prague', 'Czech Republic', 'The historic Jewish quarter of Prague, containing six synagogues, the Old Jewish Cemetery, and the Jewish Ceremonial Hall. Its core was preserved when the surrounding ghetto was demolished in the late 19th century.', 'It holds one of Europe''s most significant Jewish heritage sites, including the haunting medieval cemetery with thousands of stacked tombstones.', 120, NULL, 0, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:czech-republic-prague-dancing-house', 'Dancing House', 'landmark', 50.075500, 14.414300, 'Prague', 'Czech Republic', 'A deconstructivist office building completed in 1996, designed by Vlado Milunic and Frank Gehry on the Rasin Embankment. Its curved twisting form is nicknamed Fred and Ginger.', 'It is Prague''s signature modern landmark — a startling counterpoint to the city''s Gothic and Baroque streetscape.', 30, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:czech-republic-prague-vysehrad', 'Vysehrad', 'fortress', 50.064700, 14.417200, 'Prague', 'Czech Republic', 'A historic fort on a hill above the Vltava, founded in the 10th century, containing the Basilica of St. Peter and St. Paul and a cemetery with the graves of Czech cultural figures including Dvorak and Smetana. It is wrapped in the legends of Princess Libuse.', 'It offers a quieter, locals'' Prague with panoramic river views and the country''s most revered cultural pantheon.', 90, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:czech-republic-prague-letna-park', 'Letna Park', 'park', 50.095000, 14.418000, 'Prague', 'Czech Republic', 'A large hilltop park on the north bank of the Vltava, overlooking Prague''s bridges and historic core. It contains the giant metronome that replaced a Stalin monument in 1991.', 'Its bluff delivers the classic postcard view of Prague''s six bridges and is a favorite locals'' sunset spot.', 60, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:czech-republic-prague-municipal-house', 'Municipal House', 'landmark', 50.087900, 14.428300, 'Prague', 'Czech Republic', 'A civic landmark in Art Nouveau style completed in 1912, featuring decoration by Alphonse Mucha and other leading Czech artists. It houses Smetana Hall, a major concert venue, and historic cafes.', 'It is the most opulent Art Nouveau building in the city and the room where Czechoslovak independence was declared in 1918.', 60, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:china-shanghai-the-bund', 'The Bund', 'viewpoint', 31.239700, 121.490800, 'Shanghai', 'China', 'A mile-long waterfront promenade along the Huangpu River lined with 52 historic colonial-era buildings in Art Deco, Gothic, and Beaux-Arts styles. It faces the futuristic Pudong skyline across the river.', 'It is the single most iconic view in Shanghai, contrasting 1920s European architecture with the city''s space-age skyscrapers.', 90, NULL, 1, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:china-shanghai-oriental-pearl-tower', 'Oriental Pearl Tower', 'tower', 31.239700, 121.499800, 'Shanghai', 'China', 'A 468-meter television tower in Pudong featuring eleven distinctive spheres and a glass-floored observation deck. Completed in 1994, it was China''s tallest structure for a decade.', 'Its instantly recognizable pink-orb silhouette defines the Shanghai skyline and offers panoramic city views.', 120, NULL, 1, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:china-shanghai-yu-garden', 'Yu Garden', 'garden', 31.227200, 121.492000, 'Shanghai', 'China', 'A classical Chinese garden first built in 1559 during the Ming Dynasty, featuring rockeries, pavilions, ponds, and zigzag bridges across two hectares. It is surrounded by the bustling Yuyuan Bazaar.', 'It is Shanghai''s finest preserved classical garden and a rare glimpse of pre-modern Chinese aesthetics in the heart of the city.', 120, NULL, 1, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:china-shanghai-shanghai-tower', 'Shanghai Tower', 'observation_deck', 31.233600, 121.505500, 'Shanghai', 'China', 'At 632 meters, this twisting megatall skyscraper is China''s tallest building and the world''s third-tallest. Its observation deck on the 118th floor is among the highest in the world.', 'It offers the highest viewpoint in Shanghai and is reached by one of the world''s fastest elevators.', 120, NULL, 1, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:china-shanghai-nanjing-road', 'Nanjing Road', 'district', 31.236000, 121.475000, 'Shanghai', 'China', 'Shanghai''s main shopping street stretching roughly 5.5 km from the Bund to Jing''an Temple, with a famous pedestrian-only stretch lit by neon at night. It hosts hundreds of department stores, boutiques, and historic shops.', 'It is one of the world''s busiest shopping streets and quintessential Shanghai street life and neon spectacle.', 90, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:china-shanghai-shanghai-museum', 'Shanghai Museum', 'museum', 31.230500, 121.475600, 'Shanghai', 'China', 'A major museum of ancient Chinese art on People''s Square, housed in a distinctive round-topped, square-based building completed in 1996. Its collection includes bronzes, ceramics, calligraphy, and jade.', 'It holds one of the finest collections of Chinese antiquities in the world, with free admission to world-class galleries.', 180, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:china-shanghai-jing-an-temple', 'Jing''an Temple', 'temple', 31.223600, 121.445200, 'Shanghai', 'China', 'An active Buddhist temple founded in 247 AD and reconstructed in golden-roofed Song-style architecture. It sits incongruously among glass skyscrapers in central Shanghai.', 'The contrast of a gilded ancient temple framed by modern high-rises is a uniquely Shanghai sight.', 60, NULL, 0, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:china-shanghai-tianzifang', 'Tianzifang', 'district', 31.210600, 121.465800, 'Shanghai', 'China', 'A maze of narrow shikumen (stone-gate) lane houses in the former French Concession converted into a labyrinth of small cafes, boutiques, art studios, and bars. It preserves a 1930s residential street pattern.', 'It is the best-preserved old-Shanghai laneway neighborhood you can wander freely, mixing local life with creative shops.', 120, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:china-shanghai-xintiandi', 'Xintiandi', 'district', 31.220700, 121.475600, 'Shanghai', 'China', 'A pedestrian district in the former French Concession built from restored shikumen lane houses now hosting upscale restaurants, bars, and shops. It also contains the site of the First National Congress of the Communist Party.', 'It is Shanghai''s polished showcase of preserved-and-repurposed colonial-era architecture and a key social hub.', 90, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:china-shanghai-former-french-concession', 'Former French Concession', 'district', 31.212600, 121.458000, 'Shanghai', 'China', 'A leafy historic area south and west of the city center developed under French administration from 1849 to 1943, characterized by plane-tree-lined streets and European villa architecture. Today it is one of Shanghai''s most fashionable neighborhoods.', 'Strolling its quiet tree-shaded streets reveals a side of Shanghai that feels more Paris than China.', 120, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:china-shanghai-shanghai-disneyland', 'Shanghai Disneyland', 'theme_park', 31.143400, 121.657300, 'Shanghai', 'China', 'A 963-acre Disney theme park resort that opened in 2016 in Pudong, featuring the world''s largest Enchanted Storybook Castle. It includes seven themed lands and the TRON Lightcycle roller coaster.', 'It is mainland China''s flagship Disney park with attractions found nowhere else in the world.', 480, NULL, 0, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:china-shanghai-zhujiajiao-ancient-water-town', 'Zhujiajiao Ancient Water Town', 'historic', 31.111900, 121.053100, 'Shanghai', 'China', 'A 1,700-year-old canal town on Shanghai''s western outskirts with 36 stone bridges, narrow waterways, and Ming and Qing dynasty architecture. It is the best-preserved water town within Shanghai municipality.', 'It offers a day-trip glimpse of traditional canal-side Jiangnan life without leaving Shanghai.', 240, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:taiwan-taipei-taipei-101', 'Taipei 101', 'observation_deck', 25.033800, 121.564500, 'Taipei', 'Taiwan', 'A 508-meter supertall skyscraper that held the title of world''s tallest building from 2004 to 2010, featuring an observation deck on the 89th floor and one of the world''s fastest elevators. Its bamboo-inspired tiered design is the symbol of modern Taipei.', 'It''s the defining icon of the Taipei skyline and offers the city''s most sweeping panoramic view from its observation deck.', 120, NULL, 1, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:taiwan-taipei-national-palace-museum', 'National Palace Museum', 'museum', 25.102300, 121.548500, 'Taipei', 'Taiwan', 'One of the largest museums of Chinese art and artifacts in the world, housing nearly 700,000 pieces spanning 8,000 years of Chinese history, including the famous Jadeite Cabbage. The collection was relocated from Beijing''s Forbidden City during the Chinese Civil War.', 'It holds the world''s most comprehensive collection of imperial Chinese treasures — unmatched anywhere on Earth.', 180, NULL, 1, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:taiwan-taipei-chiang-kai-shek-memorial-hall', 'Chiang Kai-shek Memorial Hall', 'monument', 25.034700, 121.521900, 'Taipei', 'Taiwan', 'A massive white marble monument with a blue octagonal roof built in 1980 to honor Taiwan''s former president, set within Liberty Square alongside the National Theater and Concert Hall. Visitors can watch the hourly changing of the honor guard ceremony.', 'It''s Taipei''s grandest civic landmark and the ceremonial heart of the city''s modern history.', 90, NULL, 1, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:taiwan-taipei-longshan-temple', 'Longshan Temple', 'temple', 25.037200, 121.499800, 'Taipei', 'Taiwan', 'Taipei''s oldest and most famous temple, founded in 1738 by Chinese settlers from Fujian, dedicated to Guanyin and dozens of folk deities. The ornate Qing-dynasty-style complex is an active center of worship in the historic Wanhua district.', 'It''s the spiritual heart of old Taipei and offers an unfiltered glimpse of Taiwan''s living folk religion.', 45, NULL, 1, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:taiwan-taipei-shilin-night-market', 'Shilin Night Market', 'market', 25.087900, 121.524000, 'Taipei', 'Taiwan', 'Taipei''s largest and most famous night market, sprawling across multiple blocks with hundreds of food stalls, games, and shops. Famous for stinky tofu, oyster omelets, giant fried chicken cutlets, and bubble tea.', 'Night markets are central to Taiwanese culture, and Shilin is the largest and most iconic of them all.', 120, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:taiwan-taipei-elephant-mountain', 'Elephant Mountain', 'viewpoint', 25.027600, 121.571000, 'Taipei', 'Taiwan', 'A short but steep hiking trail in the Four Beasts mountain range, climbing to a series of rock platforms that offer the postcard view of Taipei 101 and the city skyline. The full hike is roughly 20-30 minutes of stairs.', 'It delivers the single best free photo of Taipei 101 against the city skyline, especially at sunset.', 90, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:taiwan-taipei-beitou-hot-springs', 'Beitou Hot Springs', 'experience', 25.136900, 121.507000, 'Taipei', 'Taiwan', 'A historic hot spring district in northern Taipei developed during the Japanese colonial era, featuring the steaming sulfuric Thermal Valley, public bathhouses, and the wooden Beitou Hot Spring Museum. The springs have been used for over a century.', 'Soaking in Beitou''s geothermal waters is one of Taipei''s most distinctive cultural experiences.', 150, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:taiwan-taipei-dadaocheng-dihua-street', 'Dadaocheng Dihua Street', 'historic', 25.055600, 121.509900, 'Taipei', 'Taiwan', 'Taipei''s oldest commercial street, lined with preserved Qing-dynasty, Baroque-revival, and Japanese-era shophouses that have sold dried goods, Chinese medicine, and tea for over 150 years. It''s the historic heart of Taipei''s merchant district.', 'It''s the best-preserved historic streetscape in Taipei and a window into the city''s 19th-century commercial roots.', 90, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:taiwan-taipei-bao-an-temple', 'Bao''an Temple', 'temple', 25.073100, 121.515800, 'Taipei', 'Taiwan', 'A 200-year-old Taoist temple dedicated to the medicine god Baosheng Dadi, recognized by UNESCO with an Asia-Pacific Heritage Award for its restoration. It''s renowned for its exceptional stone carvings, woodwork, and ceiling paintings.', 'It''s considered one of Taiwan''s finest examples of traditional temple craftsmanship.', 45, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:taiwan-taipei-confucius-temple', 'Confucius Temple', 'temple', 25.072600, 121.516300, 'Taipei', 'Taiwan', 'A serene temple complex in the Dalongdong district built in the southern Fujian style, dedicated to the philosopher Confucius. Unlike Taipei''s other temples, it''s deliberately understated, reflecting Confucian ideals of simplicity.', 'It offers a calm, scholarly counterpoint to Taipei''s busier folk-religion temples.', 45, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:taiwan-taipei-ximending', 'Ximending', 'district', 25.042100, 121.507600, 'Taipei', 'Taiwan', 'Taipei''s main pedestrian shopping and entertainment district, often called the ''Harajuku of Taipei,'' packed with fashion boutiques, street performers, cinemas, and street food. It''s been the city''s youth culture hub since the Japanese colonial era.', 'It''s the pulse of Taipei''s youth and pop culture, day or night.', 120, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:taiwan-taipei-daan-forest-park', 'Daan Forest Park', 'park', 25.026300, 121.535400, 'Taipei', 'Taiwan', 'A 26-hectare urban green space often called the ''lungs of Taipei,'' featuring an ecological pond, bamboo groves, and walking paths. It opened in 1994 on the site of a former military housing complex.', 'It''s the city''s most beloved urban escape and a window into everyday Taipei life.', 60, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:united-states-los-angeles-hollywood-sign', 'Hollywood Sign', 'landmark', 34.134100, -118.321500, 'Los Angeles', 'United States', 'A 45-foot-tall white letter sign on Mount Lee in the Hollywood Hills, originally erected in 1923 as a real estate advertisement reading ''Hollywoodland.'' It is viewable from numerous vantage points around the city but cannot be approached up close.', 'It is the single most recognizable symbol of the global film industry and of Los Angeles itself.', 45, NULL, 1, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:united-states-los-angeles-griffith-observatory', 'Griffith Observatory', 'observation_deck', 34.118400, -118.300400, 'Los Angeles', 'United States', 'A 1935 Art Deco public observatory on the south-facing slope of Mount Hollywood inside Griffith Park, featuring planetarium shows, astronomy exhibits, and the Zeiss telescope. Admission to the building and grounds is free.', 'It offers the definitive postcard view of the Los Angeles basin and the Hollywood Sign and is one of the most filmed locations in the city.', 120, NULL, 1, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:united-states-los-angeles-santa-monica-pier', 'Santa Monica Pier', 'landmark', 34.009400, -118.497300, 'Los Angeles', 'United States', 'A historic wooden pier built in 1909 that juts into the Pacific Ocean and houses Pacific Park, an amusement area with a solar-powered Ferris wheel, plus an aquarium and arcade. It marks the western terminus of historic Route 66.', 'It is the quintessential Southern California beach scene and the iconic ''end of the road'' for cross-country travelers.', 120, NULL, 1, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:united-states-los-angeles-hollywood-walk-of-fame', 'Hollywood Walk of Fame', 'landmark', 34.101600, -118.326700, 'Los Angeles', 'United States', 'A 1.3-mile stretch of sidewalk along Hollywood Boulevard and Vine Street embedded with more than 2,700 brass-rimmed terrazzo stars honoring figures from entertainment. The walk has been adding stars since 1960.', 'Walking the stars and seeing the TCL Chinese Theatre handprints is the classic Hollywood pilgrimage.', 60, NULL, 1, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:united-states-los-angeles-getty-center', 'Getty Center', 'museum', 34.078000, -118.474100, 'Los Angeles', 'United States', 'A Richard Meier-designed hilltop campus in Brentwood housing the J. Paul Getty Museum''s European paintings, drawings, sculpture, and decorative arts, along with extensive gardens. Admission is free; only parking is charged.', 'Its combination of world-class art, modernist travertine architecture, and panoramic city views is unrivalled in LA.', 180, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:united-states-los-angeles-venice-beach-boardwalk', 'Venice Beach Boardwalk', 'district', 33.985000, -118.469500, 'Los Angeles', 'United States', 'A 2.5-mile beachfront promenade lined with street performers, vendors, skate parks, and the original outdoor Muscle Beach gym. It dates to the early 20th-century ''Venice of America'' resort development.', 'It is the bohemian, sun-soaked counterpart to Santa Monica and a defining slice of Los Angeles beach culture.', 90, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:united-states-los-angeles-universal-studios-hollywood', 'Universal Studios Hollywood', 'theme_park', 34.138100, -118.353400, 'Los Angeles', 'United States', 'A major film studio and theme park in Universal City featuring rides themed to Harry Potter, Jurassic World, and Super Nintendo World, plus the working-backlot Studio Tour. It has operated as a public tour since 1964.', 'It is the only theme park in the world built around an active Hollywood studio backlot.', 360, NULL, 0, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:united-states-los-angeles-the-broad', 'The Broad', 'museum', 34.054500, -118.250700, 'Los Angeles', 'United States', 'A contemporary art museum on Grand Avenue downtown, opened in 2015 in a distinctive ''veil and vault'' building designed by Diller Scofidio + Renfro. It houses the Broad collection including Yayoi Kusama''s Infinity Mirror Rooms.', 'General admission is free and it holds one of the most important postwar and contemporary art collections in the country.', 120, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:united-states-los-angeles-walt-disney-concert-hall', 'Walt Disney Concert Hall', 'landmark', 34.055400, -118.249800, 'Los Angeles', 'United States', 'The Frank Gehry-designed home of the LA Philharmonic, opened in 2003, clad in curving stainless-steel sails. The exterior, lobby, and rooftop garden are open to the public for free self-guided visits.', 'It is the masterpiece of modern Los Angeles architecture and one of Gehry''s signature buildings worldwide.', 45, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:united-states-los-angeles-olvera-street', 'Olvera Street', 'historic', 34.057300, -118.237800, 'Los Angeles', 'United States', 'A short, pedestrian Mexican-themed marketplace in El Pueblo de Los Angeles Historical Monument, the city''s birthplace, lined with adobe buildings, craft stalls, and historic structures including the 1818 Avila Adobe. It was reopened as a marketplace in 1930.', 'It preserves the original 1781 founding site of Los Angeles and is the city''s oldest street.', 60, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:united-states-los-angeles-rodeo-drive', 'Rodeo Drive', 'district', 34.069600, -118.403000, 'Los Angeles', 'United States', 'A three-block luxury shopping street in Beverly Hills lined with flagship boutiques from brands such as Chanel, Gucci, and Louis Vuitton. The famous stretch runs between Wilshire and Santa Monica Boulevards.', 'It is the most famous luxury shopping street in the United States and an essential Beverly Hills photo stop.', 60, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:united-states-los-angeles-la-brea-tar-pits-and-museum', 'La Brea Tar Pits and Museum', 'museum', 34.063900, -118.355600, 'Los Angeles', 'United States', 'An active paleontological site on Wilshire Boulevard''s Miracle Mile where natural asphalt has trapped and preserved Ice Age fossils for tens of thousands of years. The adjacent museum displays mammoths, saber-toothed cats, and dire wolves excavated on site.', 'It is the only active urban Ice Age fossil dig in the world, in the middle of central LA.', 90, NULL, 0, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:australia-sydney-sydney-opera-house', 'Sydney Opera House', 'landmark', -33.856800, 151.215300, 'Sydney', 'Australia', 'A UNESCO World Heritage-listed multi-venue performing arts centre on Bennelong Point, famous for its sail-shaped concrete shells designed by Danish architect Jorn Utzon and opened in 1973.', 'It is the defining symbol of Sydney and one of the most recognizable buildings on Earth, instantly identifying the city in any photograph.', 90, NULL, 1, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:australia-sydney-sydney-harbour-bridge', 'Sydney Harbour Bridge', 'landmark', -33.852300, 151.210800, 'Sydney', 'Australia', 'A steel through-arch bridge spanning Sydney Harbour, opened in 1932 and affectionately nicknamed ''The Coathanger,'' carrying rail, vehicle, bicycle and pedestrian traffic between the CBD and the North Shore.', 'Walking across its pedestrian path or climbing its arch offers the single best view of the Opera House and harbour, a quintessential Sydney experience.', 60, NULL, 1, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:australia-sydney-bondi-beach', 'Bondi Beach', 'beach', -33.891500, 151.276700, 'Sydney', 'Australia', 'A one-kilometre crescent of golden sand in Sydney''s eastern suburbs, lined with surf clubs, cafes and the iconic Bondi Icebergs ocean pool at the southern end.', 'It is Australia''s most famous beach and the cultural heart of Sydney''s surf and outdoor lifestyle, unmissable for any first-time visitor.', 120, NULL, 1, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:australia-sydney-royal-botanic-garden-sydney', 'Royal Botanic Garden Sydney', 'garden', -33.864200, 151.216600, 'Sydney', 'Australia', 'A 30-hectare public botanical garden wrapping around Farm Cove, established in 1816 as Australia''s oldest scientific institution, with themed gardens and harbour-side lawns.', 'It offers the most beautiful free walking route to Mrs Macquarie''s Chair, where you can frame the Opera House and Harbour Bridge together in one shot.', 90, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:australia-sydney-the-rocks', 'The Rocks', 'district', -33.859900, 151.209000, 'Sydney', 'Australia', 'Sydney''s oldest neighbourhood, sitting beneath the Harbour Bridge, with sandstone laneways, colonial-era pubs, weekend markets and the city''s earliest European buildings dating from the 1790s.', 'It is where modern Australia began and remains the most atmospheric pocket of historic Sydney, with harbour views around every corner.', 120, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:australia-sydney-taronga-zoo-sydney', 'Taronga Zoo Sydney', 'zoo', -33.843000, 151.241000, 'Sydney', 'Australia', 'A 28-hectare harbourside zoo opened in 1916 on the north shore, home to more than 4,000 animals including koalas, kangaroos, platypus and Tasmanian devils.', 'It combines the chance to see Australia''s unique wildlife up close with arguably the world''s most spectacular zoo view back across the harbour to the city skyline.', 240, NULL, 0, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:australia-sydney-queen-victoria-building', 'Queen Victoria Building', 'historic', -33.871700, 151.206900, 'Sydney', 'Australia', 'A grand Romanesque Revival shopping arcade built in 1898, occupying an entire city block on George Street and restored in the 1980s with stained glass, mosaic floors and a central dome.', 'It is the most beautiful heritage building in the CBD and a free way to step inside Victorian-era Sydney while sheltering from rain or summer heat.', 60, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:australia-sydney-sydney-tower-eye', 'Sydney Tower Eye', 'observation_deck', -33.870400, 151.208900, 'Sydney', 'Australia', 'At 309 metres, the tallest structure in Sydney, with an enclosed observation deck and an outdoor Skywalk platform 268 metres above Centrepoint in the CBD.', 'It offers the only 360-degree panorama of Sydney, taking in the harbour, Blue Mountains and Pacific coastline in a single sweep.', 75, NULL, 0, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:australia-sydney-manly-beach', 'Manly Beach', 'beach', -33.796900, 151.287600, 'Sydney', 'Australia', 'A long ocean beach on Sydney''s northern peninsula, reached by a scenic 30-minute ferry from Circular Quay and backed by the pine-lined Corso shopping strip.', 'The ferry ride itself is one of Sydney''s great experiences, and Manly delivers a relaxed, locals-favourite alternative to busy Bondi.', 180, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:australia-sydney-art-gallery-of-new-south-wales', 'Art Gallery of New South Wales', 'art_gallery', -33.868800, 151.217300, 'Sydney', 'Australia', 'The state''s flagship public art museum on the edge of the Domain, founded in 1871, with a major collection of Australian, Aboriginal, European and Asian art across two buildings including the 2022 Sydney Modern wing.', 'It holds the country''s deepest collection of Aboriginal and Torres Strait Islander art and is free to enter, making it the single best cultural stop in the city.', 150, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:australia-sydney-darling-harbour', 'Darling Harbour', 'district', -33.874000, 151.198900, 'Sydney', 'Australia', 'A redeveloped waterfront precinct west of the CBD, lined with promenades, restaurants and family attractions including SEA LIFE Sydney Aquarium, WILD LIFE Sydney Zoo and the Australian National Maritime Museum.', 'It is Sydney''s pedestrianized entertainment hub, ideal for a sunset stroll and the most concentrated cluster of family-friendly attractions in the city.', 120, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:australia-sydney-st-mary-s-cathedral', 'St Mary''s Cathedral', 'cathedral', -33.870900, 151.213400, 'Sydney', 'Australia', 'The seat of the Roman Catholic Archbishop of Sydney, a Gothic Revival sandstone cathedral begun in 1868 and finally crowned with its twin spires in 2000, facing Hyde Park.', 'It is the longest church in Australia and a striking example of colonial Gothic architecture, free to enter and right beside Hyde Park.', 45, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:france-chateaux-of-the-loire-valley', 'Chateaux of the Loire Valley', 'historic', 47.390000, 0.690000, '', 'France', 'A UNESCO-listed stretch of the Loire River dotted with more than 300 Renaissance chateaux, including Chambord, Chenonceau, and Villandry, set among forests, vineyards, and formal gardens. The valley was the royal heartland of France during the 15th and 16th centuries.', 'Nowhere else concentrates so many fairytale royal castles in a single pastoral landscape, defining France''s regal heritage.', 300, NULL, 1, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:france-french-alps', 'French Alps', 'national_park', 45.832600, 6.865200, '', 'France', 'The French Alps stretch from Lake Geneva to the Mediterranean and include Mont Blanc, Europe''s highest peak, along with world-class ski resorts like Chamonix, Courchevel, and Val d''Isere. The range offers glaciers, alpine villages, and hiking on the Tour du Mont Blanc.', 'The French Alps are the birthplace of modern alpinism and the most celebrated ski destination in Europe.', 480, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:france-provence-lavender-fields', 'Provence Lavender Fields', 'experience', 43.949300, 5.403600, '', 'France', 'Each summer, the Valensole Plateau, Luberon, and Sault region of Provence bloom with vast purple lavender fields, peaking from late June through mid-July. The landscape is dotted with stone villages, abbeys like Senanque, and sunflower fields.', 'The lavender fields are the iconic image of summer in southern France and a defining sensory experience of Provence.', 180, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:france-normandy-d-day-beaches', 'Normandy D-Day Beaches', 'historic', 49.366700, -0.866700, '', 'France', 'The stretch of Normandy coastline including Omaha, Utah, Gold, Juno, and Sword beaches was the site of the June 6, 1944 Allied landings that began the liberation of Western Europe. The area preserves bunkers, cemeteries, and museums commemorating the invasion.', 'The D-Day beaches are among the most significant World War II pilgrimage sites in the world and a defining piece of modern French history.', 300, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:spain-camino-de-santiago', 'Camino de Santiago', 'experience', 42.878200, -8.544800, '', 'Spain', 'A network of ancient pilgrimage routes traversing northern Spain, all converging on the Cathedral of Santiago de Compostela in Galicia. Walked by hundreds of thousands of pilgrims annually, the most famous route (Camino Francés) spans roughly 800 km from the French Pyrenees.', 'It is the world''s most iconic long-distance pilgrimage and a defining cultural journey through Spanish landscapes and villages.', 480, NULL, 1, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:united-states-grand-canyon', 'Grand Canyon', 'national_park', 36.106900, -112.112900, '', 'United States', 'A mile-deep, 277-mile-long gorge carved by the Colorado River through layered red rock in northern Arizona. It is one of the most visited national parks in the country and a UNESCO World Heritage Site.', 'It is the single most iconic natural landscape in America and the archetypal image of the American West.', 240, NULL, 1, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:united-states-yellowstone-national-park', 'Yellowstone National Park', 'national_park', 44.428000, -110.588500, '', 'United States', 'The world''s first national park, spanning Wyoming, Montana, and Idaho, famous for geysers like Old Faithful, hot springs, and wildlife including bison, wolves, and grizzlies. It sits atop one of the largest active volcanic systems on Earth.', 'It defines the American national park ideal and offers a concentration of geothermal wonders and megafauna found nowhere else.', 360, NULL, 1, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:united-states-niagara-falls', 'Niagara Falls', 'waterfall', 43.082800, -79.074200, '', 'United States', 'A massive trio of waterfalls on the border between New York State and Ontario, Canada, with a combined flow of more than 3,160 tons of water per second. The American side is accessed via Niagara Falls State Park, the oldest state park in the U.S.', 'It is the most powerful waterfall in North America and a centerpiece of the American natural landscape.', 180, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:united-states-yosemite-national-park', 'Yosemite National Park', 'national_park', 37.865100, -119.538300, '', 'United States', 'A Sierra Nevada park in California known for granite cliffs like El Capitan and Half Dome, giant sequoia groves, and waterfalls including Yosemite Falls. It is a UNESCO World Heritage Site and a birthplace of the American conservation movement.', 'Its towering granite monoliths and waterfalls define the iconic image of the American wilderness.', 360, NULL, 1, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:turkey-pamukkale-travertines', 'Pamukkale Travertines', 'nature_reserve', 37.920300, 29.120600, '', 'Turkey', 'A natural site of brilliant white terraced pools formed by calcium-rich thermal springs cascading down a hillside in southwestern Turkey. The travertines sit alongside the ruins of the ancient Roman spa city of Hierapolis.', 'Pamukkale''s otherworldly white terraces and turquoise pools are a UNESCO-listed natural wonder unique to Turkey.', 180, NULL, 1, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:italy-amalfi-coast', 'Amalfi Coast', 'viewpoint', 40.634000, 14.602700, '', 'Italy', 'A 50-kilometer stretch of dramatic Mediterranean coastline in southern Italy featuring pastel cliffside villages like Positano, Amalfi, and Ravello. Designated a UNESCO World Heritage Site for its scenic and cultural landscape.', 'The Amalfi Coast embodies Italy''s romantic coastal ideal, blending lemon groves, sea cliffs, and ancient fishing villages.', 480, NULL, 1, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:italy-dolomites', 'Dolomites', 'national_park', 46.410200, 11.844000, '', 'Italy', 'A UNESCO-listed mountain range in northeastern Italy known for jagged pale limestone peaks, alpine meadows, and via ferrata routes. Spans the provinces of Belluno, South Tyrol, and Trentino.', 'The Dolomites are Italy''s most spectacular alpine landscape and a global benchmark for dramatic mountain scenery.', 480, NULL, 1, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:italy-cinque-terre', 'Cinque Terre', 'national_park', 44.128000, 9.709000, '', 'Italy', 'Five centuries-old fishing villages perched on the rugged Ligurian coastline, connected by hiking trails and a coastal railway. A UNESCO World Heritage Site and Italian national park.', 'Cinque Terre captures Italy''s iconic cliffside village imagery in a single hikeable stretch of Mediterranean coast.', 360, NULL, 1, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:italy-mount-etna', 'Mount Etna', 'landmark', 37.751000, 14.993400, '', 'Italy', 'Europe''s largest and most active volcano, rising 3,300 meters above eastern Sicily. A UNESCO World Heritage Site with frequent eruptions, lava fields, and summit hiking access.', 'Etna is Italy''s most iconic natural force, a living volcano that has shaped Sicilian culture and landscape for millennia.', 300, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:japan-mount-fuji', 'Mount Fuji', 'viewpoint', 35.360600, 138.727400, '', 'Japan', 'A 3,776-meter active stratovolcano straddling Shizuoka and Yamanashi prefectures, and Japan''s highest peak. Its near-perfect symmetrical cone is a UNESCO World Heritage Site and a sacred site in Shinto tradition.', 'Mount Fuji is Japan''s defining natural symbol and the country''s most recognizable landmark worldwide.', 240, NULL, 1, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:united-kingdom-scottish-highlands', 'Scottish Highlands', 'nature_reserve', 57.120000, -4.710000, '', 'United Kingdom', 'A vast mountainous region in northern Scotland encompassing Glencoe, Loch Ness, Cairngorms, and the Isle of Skye. Defined by rugged peaks, mist-covered lochs, ancient castles, and sparsely populated glens.', 'The Highlands are the wild, romantic landscape that defines Scotland in the global imagination.', 480, NULL, 1, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:united-kingdom-lake-district', 'Lake District', 'national_park', 54.460900, -3.088600, '', 'United Kingdom', 'A UNESCO World Heritage national park in northwest England featuring England''s largest lakes, highest peaks including Scafell Pike, and the literary landscape that inspired Wordsworth and Beatrix Potter.', 'The Lake District is England''s most beloved natural landscape and a cornerstone of British Romantic identity.', 360, NULL, 1, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:germany-oktoberfest', 'Oktoberfest', 'experience', 48.131600, 11.549700, '', 'Germany', 'The world''s largest folk festival, held annually for 16-18 days in late September through early October in Munich. It draws over 6 million visitors who gather in massive beer tents to celebrate Bavarian beer, food, and traditional dress.', 'It is the global archetype of German beer culture and Bavarian tradition, drawing travelers from every continent.', 300, NULL, 1, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:germany-romantic-road', 'Romantic Road', 'experience', 49.398800, 10.185600, '', 'Germany', 'A 460-kilometer scenic route through southern Germany linking medieval walled towns, Bavarian villages, and fairytale castles between Wurzburg and Fussen. It passes Rothenburg ob der Tauber, Dinkelsbuhl, and the foothills of the Alps.', 'It is the definitive road trip through storybook Germany, stringing together half-timbered towns and castles into one continuous landscape.', 480, NULL, 1, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:germany-black-forest', 'Black Forest', 'nature_reserve', 48.266700, 8.183300, '', 'Germany', 'A large forested mountain range in southwestern Germany known for dense evergreen woods, cuckoo clocks, spa towns, and the source of the Danube River. It spans roughly 160 kilometers north to south along the French border.', 'It is the iconic German wilderness that inspired Grimm''s fairy tales and remains synonymous with the country''s folklore.', 360, NULL, 1, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:germany-rhine-valley', 'Rhine Valley', 'river', 50.150000, 7.716700, '', 'Germany', 'The Upper Middle Rhine Valley is a UNESCO-listed 65-kilometer stretch of the Rhine River between Bingen and Koblenz, lined with more than 40 hilltop castles, terraced vineyards, and medieval wine villages. River cruises and the Loreley rock are signature experiences.', 'It is the country''s most legendary river landscape, packing castles, vineyards, and Romantic-era scenery into one navigable corridor.', 300, NULL, 1, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:germany-bavarian-alps', 'Bavarian Alps', 'national_park', 47.416700, 11.000000, '', 'Germany', 'The northern range of the Alps along Germany''s southern border with Austria, home to the country''s highest peak Zugspitze, alpine lakes like Konigssee, and Berchtesgaden National Park. The region also hosts Neuschwanstein Castle and the resort town of Garmisch-Partenkirchen.', 'It delivers Germany''s most dramatic mountain scenery and the fairytale castle backdrop the country is famous for worldwide.', 360, NULL, 1, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:germany-christmas-markets', 'Christmas Markets', 'experience', 49.452100, 11.076700, '', 'Germany', 'A nationwide tradition of open-air Advent markets held in town squares from late November through Christmas Eve, with Nuremberg''s Christkindlesmarkt, Dresden''s Striezelmarkt, and Cologne''s markets among the most famous. Vendors sell gluhwein, lebkuchen, handcrafted ornaments, and wooden toys.', 'Germany invented the modern Christmas market, and the country''s winter markets remain the global standard for the tradition.', 180, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:thailand-thai-island-beaches', 'Thai Island Beaches', 'beach', 7.880400, 98.392300, '', 'Thailand', 'A constellation of tropical islands across the Andaman Sea and Gulf of Thailand, including Phuket, Phi Phi, Krabi, Koh Samui, and Koh Lanta, known for limestone karsts, turquoise water, and white-sand beaches. The islands offer snorkeling, diving, longtail boat tours, and beach resorts.', 'Thailand''s islands and beaches are the country''s defining tropical escape and a primary draw for international travelers.', 480, NULL, 1, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:thailand-thai-buddhist-temples-wats', 'Thai Buddhist Temples (Wats)', 'religious', 15.870000, 100.992500, '', 'Thailand', 'Thailand has over 40,000 Buddhist temples (wats) spread across the country, featuring gilded stupas, ornate prangs, and reclining or seated Buddha images. Iconic examples include Wat Pho, Wat Arun, Wat Phra Kaew, Wat Rong Khun, and Doi Suthep.', 'Theravada Buddhist temple architecture is the visual signature of Thailand and central to its cultural identity.', 90, NULL, 1, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:thailand-thai-street-food', 'Thai Street Food', 'experience', 15.870000, 100.992500, '', 'Thailand', 'A nationwide culinary tradition of open-air food stalls, night markets, and hawker carts serving pad thai, som tam, mango sticky rice, boat noodles, and grilled satay. Bangkok, Chiang Mai, and Phuket have especially famous street-food scenes.', 'Thai street food is globally recognized as one of the world''s great cuisines and a defining sensory experience of visiting Thailand.', 60, NULL, 1, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:thailand-elephant-sanctuaries', 'Elephant Sanctuaries', 'wildlife', 18.788300, 98.985300, '', 'Thailand', 'Ethical elephant sanctuaries concentrated in northern Thailand (especially around Chiang Mai) and southern regions, where rescued Asian elephants are cared for in semi-wild settings. Visitors can observe, feed, and bathe elephants without riding them.', 'The Asian elephant is Thailand''s national animal and encountering them in sanctuaries is a signature Thai wildlife experience.', 240, NULL, 0, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:greece-meteora-monasteries', 'Meteora Monasteries', 'religious', 39.721700, 21.630600, '', 'Greece', 'A complex of six active Eastern Orthodox monasteries built atop towering sandstone pillars in central Greece, dating from the 14th century. The site is a UNESCO World Heritage landmark for both its geology and spiritual heritage.', 'The surreal sight of clifftop monasteries floating above the plains is one of Greece''s most singular landscapes.', 240, NULL, 1, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:greece-mount-olympus', 'Mount Olympus', 'national_park', 40.085000, 22.358500, '', 'Greece', 'The highest mountain in Greece at 2,917 meters, mythological home of the twelve Olympian gods and Greece''s first national park. Its slopes host hiking trails, alpine refuges, and rare endemic flora.', 'Olympus links Greece''s mythological identity directly to a hikable, real-world peak unlike any other in the world.', 360, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:austria-viennese-coffee-house-culture', 'Viennese Coffee House Culture', 'experience', 48.208200, 16.373800, '', 'Austria', 'Recognized by UNESCO as Intangible Cultural Heritage, Austria''s coffee house tradition revolves around marble-topped tables, newspapers, and unhurried hours over a Melange or Einspanner. Historic cafes like Central, Sacher, and Hawelka anchor a centuries-old ritual.', 'The coffee house is uniquely Austrian, where intellectual life, pastries, and slow time have defined urban culture since the 17th century.', 90, NULL, 1, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:austria-salzkammergut-lake-district', 'Salzkammergut Lake District', 'nature_reserve', 47.616700, 13.650000, '', 'Austria', 'A region of 76 alpine lakes set among mountains east of Salzburg, including Hallstatter See, Wolfgangsee, and Mondsee. The cultural landscape of Hallstatt-Dachstein/Salzkammergut is a UNESCO World Heritage Site.', 'The fairy-tale combination of mirror lakes, alpine peaks, and storybook villages like Hallstatt is one of Austria''s most iconic landscapes.', 300, NULL, 1, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:austria-wachau-valley-wine-region', 'Wachau Valley Wine Region', 'experience', 48.366700, 15.400000, '', 'Austria', 'A UNESCO-listed stretch of the Danube between Melk and Krems lined with terraced vineyards producing Gruner Veltliner and Riesling. Baroque abbeys, medieval ruins, and riverside villages punctuate the 40-kilometer valley.', 'Wachau is Austria''s most celebrated wine landscape, blending river cruises, world-class whites, and centuries-old monasteries.', 240, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:portugal-douro-valley-wine-region', 'Douro Valley Wine Region', 'experience', 41.149600, -7.613100, '', 'Portugal', 'The world''s oldest demarcated wine region, a UNESCO World Heritage landscape of terraced vineyards carved into steep schist hillsides along the Douro River. It is the birthplace of Port wine and home to centuries-old quintas producing both fortified and table wines.', 'The terraced river valley is Portugal''s signature landscape and the origin of its most iconic export, Port wine.', 360, NULL, 1, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:portugal-algarve-coast', 'Algarve Coast', 'beach', 37.097900, -8.203000, '', 'Portugal', 'Portugal''s southern coastline stretching roughly 150 km, defined by golden limestone cliffs, sea caves, hidden coves, and turquoise Atlantic waters. It includes iconic spots like Benagil Cave, Ponta da Piedade, and Praia da Marinha.', 'The dramatic cliff-and-cave coastline is the image most travelers associate with Portuguese beach holidays.', 300, NULL, 1, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:portugal-madeira-island', 'Madeira Island', 'nature_reserve', 32.760700, -16.959500, '', 'Portugal', 'A Portuguese subtropical archipelago in the Atlantic Ocean about 1,000 km southwest of Lisbon, known for its volcanic peaks, UNESCO-listed Laurisilva forest, levada walking trails, and fortified Madeira wine. The main island rises to 1,862 m at Pico Ruivo.', 'Madeira is Portugal''s signature island destination, combining dramatic mountain hiking with year-round subtropical climate.', 480, NULL, 1, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:portugal-azores-archipelago', 'Azores Archipelago', 'nature_reserve', 37.741200, -25.675600, '', 'Portugal', 'A volcanic archipelago of nine Portuguese islands in the mid-Atlantic, famed for crater lakes, hot springs, whale watching, and dramatic green calderas like Sete Cidades and Lagoa do Fogo. The islands sit on the meeting point of three tectonic plates.', 'The Azores are Portugal''s wild Atlantic frontier, offering volcanic landscapes and whale watching found nowhere else in Europe.', 480, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:saudi-arabia-empty-quarter-rub-al-khali', 'Empty Quarter (Rub'' al Khali)', 'nature_reserve', 20.000000, 50.000000, '', 'Saudi Arabia', 'The largest continuous sand desert in the world, covering roughly 650,000 square kilometers across the southern Arabian Peninsula. It features towering dunes up to 250 meters high and is one of the most remote and arid places on Earth.', 'The definitive Arabian desert experience and one of the planet''s last true wilderness frontiers.', 480, NULL, 1, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:saudi-arabia-edge-of-the-world-jebel-fihrayn', 'Edge of the World (Jebel Fihrayn)', 'viewpoint', 24.933300, 46.116700, '', 'Saudi Arabia', 'A dramatic 300-meter cliff escarpment in the Tuwaiq mountains northwest of Riyadh, offering uninterrupted views over an ancient sea valley that vanishes into the horizon. It is part of a 600-kilometer cliff system formed by erosion of limestone plateau.', 'The most iconic landscape viewpoint in central Arabia and a rite-of-passage day trip from Riyadh.', 240, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:malaysia-mount-kinabalu', 'Mount Kinabalu', 'national_park', 6.075300, 116.558600, '', 'Malaysia', 'Southeast Asia''s highest peak at 4,095 meters, located in Sabah''s UNESCO-listed Kinabalu Park. The mountain is a biodiversity hotspot with thousands of endemic plant species and is climbable by non-technical trekkers over two days.', 'Summiting Mount Kinabalu is the defining adventure of Malaysian Borneo and one of Asia''s most accessible major peaks.', 480, NULL, 1, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:netherlands-wadden-sea', 'Wadden Sea', 'nature_reserve', 53.400000, 5.500000, '', 'Netherlands', 'A UNESCO World Heritage tidal flat ecosystem stretching along the northern Dutch coast, famous for mudflat hiking (wadlopen) at low tide and as a major bird migration stopover. It includes the Wadden Islands of Texel, Vlieland, Terschelling, Ameland, and Schiermonnikoog.', 'The largest unbroken intertidal sand and mudflat system in the world, unique to the North Sea coast.', 300, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:india-taj-mahal', 'Taj Mahal', 'monument', 27.175100, 78.042100, '', 'India', 'A white marble mausoleum commissioned in 1632 by Mughal emperor Shah Jahan for his wife Mumtaz Mahal, located on the south bank of the Yamuna river in Agra. It is a UNESCO World Heritage Site and widely considered the finest example of Mughal architecture.', 'It is the single most recognized image of India and the symbol that defines the country to the world.', 180, NULL, 1, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:india-backwaters-of-kerala', 'Backwaters of Kerala', 'experience', 9.498100, 76.338800, '', 'India', 'A network of interconnected canals, rivers, lakes and inlets stretching along the Arabian Sea coast of Kerala, traditionally navigated by houseboats called kettuvallams. The system covers roughly 900 kilometers of waterways through palm-lined villages and paddy fields.', 'Cruising the backwaters on a houseboat is one of the signature slow-travel experiences that defines South India.', 480, NULL, 1, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:india-ganges-river', 'Ganges River', 'river', 25.317600, 83.013000, '', 'India', 'A 2,525-kilometer trans-boundary river of Asia that flows through India and Bangladesh, considered the most sacred river in Hinduism. Its banks host major pilgrimage cities including Varanasi, Haridwar and Rishikesh, where daily aarti ceremonies and ritual bathing take place.', 'The Ganges and its riverside ghats embody the spiritual core of India in a way no single monument can.', 180, NULL, 1, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:china-great-wall-of-china', 'Great Wall of China', 'historic', 40.431900, 116.570400, '', 'China', 'A series of fortifications stretching over 13,000 miles across northern China, built and rebuilt between the 7th century BC and the Ming dynasty. Multiple sections (Badaling, Mutianyu, Jinshanling, Simatai, Jiankou) are open to visitors.', 'It is the single most recognizable symbol of China and one of the largest construction feats in human history.', 240, NULL, 1, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:china-giant-panda-sanctuaries', 'Giant Panda Sanctuaries', 'wildlife', 30.741100, 103.119000, '', 'China', 'A network of reserves and breeding bases in Sichuan province (including Chengdu Research Base and Wolong) that protect the world''s remaining wild giant pandas. The Sichuan Giant Panda Sanctuaries are a UNESCO World Heritage Site.', 'Pandas are China''s living national emblem and can only be seen in the wild here.', 180, NULL, 1, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:china-karst-mountains-of-guangxi', 'Karst Mountains of Guangxi', 'nature_reserve', 24.761900, 110.448000, '', 'China', 'Dramatic limestone pinnacles rising from rice paddies and rivers across Guangxi, most famously along the Li River between Guilin and Yangshuo. The landscape is featured on the back of the 20 yuan banknote.', 'These surreal karst peaks are the quintessential image of classical Chinese landscape painting come to life.', 360, NULL, 1, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:china-yellow-mountain-huangshan', 'Yellow Mountain (Huangshan)', 'national_park', 30.134000, 118.165500, '', 'China', 'A UNESCO-listed mountain range in Anhui province famed for granite peaks, twisted pines, hot springs, and seas of cloud. It has inspired Chinese poets and painters for over a millennium.', 'It is the archetypal sacred Chinese mountain and a pilgrimage for landscape lovers.', 480, NULL, 0, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:china-terracotta-army', 'Terracotta Army', 'historic', 34.385300, 109.278400, '', 'China', 'A collection of over 8,000 life-sized clay soldiers, horses, and chariots buried with China''s first emperor Qin Shi Huang around 210 BC, discovered near Xi''an in 1974. It is a UNESCO World Heritage Site.', 'It is one of the greatest archaeological discoveries of the 20th century and a defining symbol of imperial China.', 180, NULL, 1, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:south-korea-dmz-korean-demilitarized-zone', 'DMZ (Korean Demilitarized Zone)', 'historic', 38.317000, 127.150000, '', 'South Korea', 'A 250-kilometer-long, 4-kilometer-wide buffer zone separating North and South Korea since the 1953 armistice, accessible via guided tours to the Joint Security Area, observation posts, and infiltration tunnels. It is simultaneously one of the world''s most militarized borders and an accidental wildlife sanctuary.', 'It is the world''s last Cold War frontier and a defining symbol of the Korean peninsula.', 360, NULL, 1, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:croatia-dalmatian-coast', 'Dalmatian Coast', 'beach', 43.508100, 16.440200, '', 'Croatia', 'A stretch of Adriatic coastline running roughly 375 km from Zadar through Split to Dubrovnik, lined with pebble beaches, walled medieval towns, and over a thousand offshore islands. The shoreline''s clear turquoise water and dramatic limestone cliffs are Croatia''s defining visual signature.', 'The Dalmatian Coast is the postcard image of Croatia and the primary reason most international travelers visit the country.', 480, NULL, 1, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:croatia-plitvice-lakes-national-park', 'Plitvice Lakes National Park', 'national_park', 44.865400, 15.582000, '', 'Croatia', 'A UNESCO World Heritage site in central Croatia featuring 16 terraced lakes connected by waterfalls cascading through forested karst canyons. Wooden boardwalks snake directly above the bright turquoise water.', 'Plitvice is Croatia''s most iconic natural wonder and the country''s single most-visited inland attraction.', 360, NULL, 1, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:croatia-krka-national-park', 'Krka National Park', 'national_park', 43.800900, 15.969200, '', 'Croatia', 'A national park along the Krka River in central Dalmatia famous for its travertine waterfalls, most notably the wide multi-tiered Skradinski Buk cascade. The park combines waterfalls, wooden walkways, and a small island monastery.', 'Krka''s accessible waterfall scenery makes it the country''s most beloved national park after Plitvice.', 300, NULL, 0, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:croatia-istrian-peninsula', 'Istrian Peninsula', 'experience', 45.240000, 13.940000, '', 'Croatia', 'A heart-shaped peninsula in northwest Croatia known for hilltop medieval villages, Roman ruins, truffle forests, olive groves, and small-batch wineries. Often compared to Tuscany for its rolling agricultural landscape and gastronomy.', 'Istria is Croatia''s culinary heartland and the country''s premier food, wine, and truffle region.', 480, NULL, 0, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:switzerland-the-swiss-alps', 'The Swiss Alps', 'viewpoint', 46.558900, 8.561400, '', 'Switzerland', 'A vast mountain range covering roughly 60% of Switzerland''s territory, encompassing iconic peaks like the Matterhorn, Eiger, Jungfrau, and Mont Blanc massif. The range is dotted with glaciers, alpine meadows, and storybook villages connected by cogwheel railways and cable cars.', 'The Alps are synonymous with Switzerland itself, defining its landscape, culture, and identity as the world''s premier mountain destination.', 480, NULL, 1, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:switzerland-aletsch-glacier', 'Aletsch Glacier', 'nature_reserve', 46.500000, 8.033300, '', 'Switzerland', 'The largest glacier in the Alps at roughly 23 kilometers long, forming the core of the Swiss Alps Jungfrau-Aletsch UNESCO World Heritage Site. Accessible via cable cars from Fiesch, Bettmeralp, and Riederalp with sweeping viewpoints over the ice.', 'Aletsch is the definitive symbol of Switzerland''s glacial landscapes and Europe''s most spectacular ice river.', 240, NULL, 0, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:canada-niagara-falls', 'Niagara Falls', 'waterfall', 43.096200, -79.037700, '', 'Canada', 'A trio of massive waterfalls straddling the Canada-US border, with the Horseshoe Falls on the Canadian side carrying the vast majority of the Niagara River''s flow. It is one of the most powerful waterfalls in North America by volume.', 'Niagara is the single most recognized natural landmark in Canada and a defining symbol of the country''s wild geography.', 180, NULL, 1, 1, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:canada-canadian-rockies', 'Canadian Rockies', 'national_park', 51.496800, -115.928100, '', 'Canada', 'A mountain range spanning Banff, Jasper, Yoho, and Kootenay National Parks in Alberta and British Columbia, featuring turquoise glacial lakes, sharp peaks, and the Icefields Parkway. The region is a UNESCO World Heritage Site.', 'Lake Louise, Moraine Lake, and Banff''s peaks are the postcard image of Canada''s wilderness.', 480, NULL, 1, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:poland-bia-owie-a-forest', 'Białowieża Forest', 'nature_reserve', 52.700000, 23.866700, '', 'Poland', 'One of the last and largest remaining parts of the immense primeval forest that once stretched across the European Plain, straddling the border between Poland and Belarus. It is home to Europe''s largest population of free-roaming European bison.', 'It is Europe''s last primeval lowland forest and the only place to see wild European bison in their native habitat.', 240, NULL, 1, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:poland-tatra-mountains', 'Tatra Mountains', 'national_park', 49.233300, 20.000000, '', 'Poland', 'The highest mountain range of the Carpathians, forming a natural border between Poland and Slovakia, with dramatic alpine peaks, glacial lakes, and the famous resort town of Zakopane as its gateway. The range includes Rysy, Poland''s highest peak at 2,499 m.', 'Poland''s only true alpine landscape and the country''s premier hiking and skiing destination.', 360, NULL, 1, 0, 'curated', date('now'));
INSERT OR REPLACE INTO attractions (id, name, category, lat, lng, city, country, description, why_visit, typical_minutes, rating, is_marquee, free_to_visit, source, last_reviewed) VALUES ('curated:poland-masurian-lake-district', 'Masurian Lake District', 'lake', 53.850000, 21.700000, '', 'Poland', 'A vast region in northeastern Poland containing more than 2,000 lakes connected by rivers and canals, formed by retreating glaciers during the last ice age. It is one of Poland''s most popular destinations for sailing, kayaking, and nature tourism.', 'Europe''s largest interconnected lake system and Poland''s defining summer landscape.', 360, NULL, 0, 1, 'curated', date('now'));

